/// The words of `cs`, between spaces, onto `acc`, the last first.
pub fn words_in(mut cs: Chars, mut word: Chars, mut acc: Strings) -> Strings {
    loop {
        if null_p(cs) {
            if null_p(word) {
                return acc;
            } else {
                return kayak_rt::heap_cons(list_to_string(reverse(word)), acc);
            }
        } else if char_eq_p(car(cs), ' ') {
            (cs, word, acc) = (cdr(cs), nil::<char>(), if null_p(word) {
                acc
            } else {
                kayak_rt::heap_cons(list_to_string(reverse(word)), acc)
            });
            continue;
        } else {
            (cs, word) = (cdr(cs), kayak_rt::heap_cons(car(cs), word));
            continue;
        }
    }
}

pub fn split_words(s: Str) -> Strings {
    reverse(words_in(string_chars(s), nil::<char>(), nil::<Str>()))
}

pub fn indices_from(i: i64, n: i64) -> List<i64> {
    if i64_gt_eq(i, n) {
        nil::<i64>()
    } else {
        kayak_rt::heap_cons(i, indices_from(i64_plus(i, 1i64), n))
    }
}

/// The newest fact at `file` and `pos` beginning `prefix`, past it; or
/// the empty string.
pub fn fact_text(mut fs: Facts, mut file: Str, mut pos: i64, mut prefix: Str) -> Str {
    loop {
        if null_p(fs) {
            return str_lit("");
        } else if {
            let tagcase_ = car(fs);
            match *tagcase_ {
                Fact::Fact(f, p, what) => {
                    (string_eq_p(f, file) && i64_eq(p, pos) && i64_gt_eq(string_length_i64(what), string_length_i64(prefix)) && string_eq_p(substring(what, int_lit(0), string_length(prefix)), prefix))
                }
            }
        } {
            let tagcase_ = car(fs);
            match *tagcase_ {
                Fact::Fact(f, p, what) => {
                    return substring(what, string_length(prefix), string_length(what));
                }
            }
        } else {
            fs = cdr(fs);
            continue;
        }
    }
}

pub fn cg_fail(why: Str) -> Void {
    error(string_append(str_lit("kayak-fx26: cells: "), why))
}

pub fn digits_i64(mut cs: Chars, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            (cs, n) = (cdr(cs), i64_plus(i64_star(n, 10i64), i64_minus(char_to_i64(car(cs)), 48i64)));
            continue;
        }
    }
}

pub fn cg_fixnum_p(n: Int) -> bool {
    (_lt_eq(n, int_lit(1152921504606846975)) && _gt_eq(n, int_lit(-1152921504606846976)))
}

pub fn call2(f: Str, x: &'static Cx, y: &'static Cx, a: i64) -> &'static Cx {
    x_app(x_var(f, a), kayak_rt::heap_cons(x, kayak_rt::heap_cons(y, kayak_rt::nil())), a)
}

// An integer literal past a fixnum, as arithmetic on fixnums: `(- 0 x)` for
// a negative; else, in base 10⁹, `(+ (* rest 1000000000) last)`, `rest`
// again so until it is a fixnum (Fixpt's `big-literal`).
pub fn big_peel(mut n: Int, mut limbs: List<Int>, mut a: i64) -> &'static Cx {
    loop {
        if cg_fixnum_p(n) {
            return big_build(x_int(n, a), limbs, a);
        } else {
            (n, limbs) = (quotient(n, int_lit(1000000000)), kayak_rt::heap_cons(remainder(n, int_lit(1000000000)), limbs));
            continue;
        }
    }
}

pub fn big_build(mut acc: &'static Cx, mut limbs: List<Int>, mut a: i64) -> &'static Cx {
    loop {
        if null_p(limbs) {
            return acc;
        } else {
            (acc, limbs) = (call2(str_lit("+"), call2(str_lit("*"), acc, x_int(int_lit(1000000000), a), a), x_int(car(limbs), a), a), cdr(limbs));
            continue;
        }
    }
}

pub fn big_literal(v: Int, a: i64) -> &'static Cx {
    if cg_fixnum_p(v) {
        x_int(v, a)
    } else if _lt(v, int_lit(0)) {
        call2(str_lit("-"), x_int(int_lit(0), a), big_peel(_minus(int_lit(0), v), nil::<Int>(), a), a)
    } else {
        big_peel(v, nil::<Int>(), a)
    }
}

// A datatype's constructors, as Fixpt's parser expands `define-datatype`:
// each `(define tag type (lambda (x1 …) (sum tag (product (1 x1) …))))`, the
// lambda where the form starts, its body where the variant does.
pub fn dt_vars(i: i64, n: i64) -> Strings {
    if i64_gt(i, n) {
        nil::<Str>()
    } else {
        kayak_rt::heap_cons(string_append(str_lit("%x"), i64_to_string(i)), dt_vars(i64_plus(i, 1i64), n))
    }
}

pub fn dt_fields(xs: Strings, i: i64, a: i64) -> Cbinds {
    if null_p(xs) {
        nil::<&'static Cbind>()
    } else {
        kayak_rt::heap_cons(cbind(i64_to_string(i), x_var(car(xs), a)), dt_fields(cdr(xs), i64_plus(i, 1i64), a))
    }
}

pub fn dt_constructors(vs: Sexps, a: i64) -> List<&'static Ctop> {
    if null_p(vs) {
        nil::<&'static Ctop>()
    } else {
        let parts = items(car(vs));
        let tag = sym_name(car(parts));
        let at = datum_pos(car(vs));
        let xs = dt_vars(1i64, size(cdr(parts)));
        kayak_rt::heap_cons(t_define(tag, true, x_lambda(xs, x_sum(tag, x_product(dt_fields(xs, 1i64, at), at), at), a)), dt_constructors(cdr(vs), a))
    }
}

// A `case` datum's kind (Fixpt's `case-kind`): 0 an integer, 1 a
// character, 2 a string, 3 a symbol, 4 a boolean, -1 none of these.
pub fn case_kind(d: &'static Sexp) -> i64 {
    let tagcase_ = d;
    match *tagcase_ {
        Sexp::Num(k, f, p) => {
            0i64
        }
        Sexp::Big(t, f, p) => {
            0i64
        }
        Sexp::Chr(c, f, p) => {
            1i64
        }
        Sexp::Str(t, f, p) => {
            2i64
        }
        Sexp::Sym(n, f, p) => {
            if (string_eq_p(n, str_lit("#t")) || string_eq_p(n, str_lit("#f"))) {
                4i64
            } else if string_eq_p(n, str_lit("#u")) {
                -1i64
            } else {
                3i64
            }
        }
        _ => {
            let other = tagcase_;
            -1i64
        }
    }
}

pub fn case_data_count(clauses: Sexps) -> i64 {
    if null_p(cdr(clauses)) {
        0i64
    } else {
        i64_plus(size(items(car(items(car(clauses))))), case_data_count(cdr(clauses)))
    }
}

// How many data of kind `k` make a `case` a search tree (Fixpt's
// `case-tree-from`).
pub fn case_tree_from(k: i64, direct: bool) -> i64 {
    if i64_eq(k, 0i64) {
        if direct {
            8i64
        } else {
            32i64
        }
    } else if i64_eq(k, 2i64) {
        16i64
    } else if i64_eq(k, 3i64) {
        if direct {
            32i64
        } else {
            64i64
        }
    } else {
        1000000000i64
    }
}

// Whether a `case`'s or `typecase`'s key is a variable, tested as it is.
pub fn case_direct_p(xs: Sexps) -> bool {
    (not(null_p(cdr(cdr(xs)))) && {
        let tagcase_ = car(xs);
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                not((string_eq_p(n, str_lit("#t")) || string_eq_p(n, str_lit("#f")) || string_eq_p(n, str_lit("#u"))))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    })
}

// The standard predicate of each shape `typecase` tests (Fixpt's
// `typecase-predicate`).
pub fn typecase_predicate(s: Str) -> Str {
    if string_eq_p(s, str_lit("int")) {
        str_lit("int?")
    } else if string_eq_p(s, str_lit("char")) {
        str_lit("char?")
    } else if string_eq_p(s, str_lit("bool")) {
        str_lit("bool?")
    } else if string_eq_p(s, str_lit("nil")) {
        str_lit("null?")
    } else if string_eq_p(s, str_lit("pair")) {
        str_lit("pair?")
    } else if string_eq_p(s, str_lit("string")) {
        str_lit("string?")
    } else if string_eq_p(s, str_lit("symbol")) {
        str_lit("symbol?")
    } else if string_eq_p(s, str_lit("procedure")) {
        str_lit("procedure?")
    } else if string_eq_p(s, str_lit("bloblet")) {
        str_lit("array?")
    } else if string_eq_p(s, str_lit("f64")) {
        str_lit("f64?")
    } else if string_eq_p(s, str_lit("f32")) {
        str_lit("f32?")
    } else if string_eq_p(s, str_lit("box")) {
        str_lit("ref?")
    } else if string_eq_p(s, str_lit("sum")) {
        str_lit("sum?")
    } else if string_eq_p(s, str_lit("product")) {
        str_lit("product?")
    } else if string_eq_p(s, str_lit("vector")) {
        str_lit("vector?")
    } else {
        str_lit("bytevector?")
    }
}

pub fn bloblet_form_p(h: Str) -> bool {
    string_member_p(h, kayak_rt::heap_cons(str_lit("make-bloblet"), kayak_rt::heap_cons(str_lit("rmake-bloblet"), kayak_rt::heap_cons(str_lit("bloblet-ref"), kayak_rt::heap_cons(str_lit("bloblet-set!"), kayak_rt::heap_cons(str_lit("bloblet-freeze"), kayak_rt::heap_cons(str_lit("bloblet-byte"), kayak_rt::heap_cons(str_lit("bloblet-set-byte!"), kayak_rt::heap_cons(str_lit("bloblet-bytes"), kayak_rt::heap_cons(str_lit("blobref-at"), kayak_rt::heap_cons(str_lit("blobref+"), kayak_rt::heap_cons(str_lit("blobref-owner"), kayak_rt::heap_cons(str_lit("blobref-offset"), kayak_rt::heap_cons(str_lit("blobref-get"), kayak_rt::heap_cons(str_lit("blobref-set!"), kayak_rt::heap_cons(str_lit("blobref-index"), kayak_rt::heap_cons(str_lit("blobref-variant!"), kayak_rt::nil())))))))))))))))))
}

// The scalar flat's layout code (`fixpt_heap::layout::FLAT_*`), or -1.
pub fn flat_code(s: Str) -> i64 {
    if string_eq_p(s, str_lit("i32")) {
        0i64
    } else if string_eq_p(s, str_lit("u32")) {
        1i64
    } else if string_eq_p(s, str_lit("i64")) {
        2i64
    } else if string_eq_p(s, str_lit("u64")) {
        3i64
    } else if string_eq_p(s, str_lit("f32")) {
        4i64
    } else if string_eq_p(s, str_lit("f64")) {
        5i64
    } else {
        -1i64
    }
}

pub fn words_i64(w: Str) -> List<i64> {
    map(lambda1s(move |x: Str| {
        digits_i64(string_chars(x), 0i64)
    }), split_words(w))
}

pub fn second_i64(xs: List<i64>) -> i64 {
    if null_p(cdr(xs)) {
        0i64
    } else {
        car(cdr(xs))
    }
}

// What blobref operation `op` at `a` takes for what the checker found of
// it, as Fixpt's `k-datum-operand` gives it: a new blobref's size, a
// scalar's code, an array's length and element size (`n << 32 | size`), a
// keyed flat sum's code (its key's width, 8, its variants' offset times
// 256); -1 for none.
pub fn blob_operand(op: Str, f: Str, a: i64) -> i64 {
    let at = lambda1(move |prefix: Str| {
        fact_text(get(cg_facts()), f, a, prefix)
    });
    if (string_eq_p(op, str_lit("blobref-at")) || string_eq_p(op, str_lit("blobref+"))) {
        let n = at(str_lit("blob-size "));
        if string_eq_p(n, str_lit("")) {
            -1i64
        } else {
            digits_i64(string_chars(n), 0i64)
        }
    } else if (string_eq_p(op, str_lit("blobref-get")) || string_eq_p(op, str_lit("blobref-set!"))) {
        flat_code(at(str_lit("blob-scalar ")))
    } else if string_eq_p(op, str_lit("blobref-index")) {
        let ns = words_i64(at(str_lit("blob-element ")));
        if null_p(ns) {
            -1i64
        } else {
            i64_plus(i64_star(second_i64(ns), 4294967296i64), car(ns))
        }
    } else if string_eq_p(op, str_lit("blobref-variant!")) {
        let ws = split_words(at(str_lit("blob-variant ")));
        if null_p(ws) {
            -1i64
        } else {
            i64_plus(i64_plus(digits_i64(string_chars(car(ws)), 0i64), 8i64), i64_star(256i64, digits_i64(string_chars(car(cdr(cdr(ws)))), 0i64)))
        }
    } else {
        -1i64
    }
}

// A generative type's conversions, `up-t` and `down-t`, each `(lambda (x)
// x)` where the form is, as Fixpt's parser's `identity-at` makes them.
pub fn generative_conversions(t: Str, a: i64) -> List<&'static Ctop> {
    kayak_rt::heap_cons(t_define(string_append(str_lit("up-"), t), true, x_lambda(kayak_rt::heap_cons(str_lit("x"), kayak_rt::nil()), x_var(str_lit("x"), a), a)), kayak_rt::heap_cons(t_define(string_append(str_lit("down-"), t), true, x_lambda(kayak_rt::heap_cons(str_lit("x"), kayak_rt::nil()), x_var(str_lit("x"), a), a)), kayak_rt::nil()))
}

// The type of the module read last: its values' names, in order.
pub fn cg_module_type() -> Ref<Strings> {
    kayak_rt::kept_constant!(ONCE: Ref<Strings>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<Str>())
    })
}

// Whether `x` is a module made where it is written.
pub fn module_made_p(x: &'static Cx) -> bool {
    let tagcase_ = x;
    match *tagcase_ {
        Cx::XModule(its, a) => {
            true
        }
        Cx::XReshape(y, ps, a) => {
            let tagcase_ = y;
            match *tagcase_ {
                Cx::XModule(its, b) => {
                    true
                }
                _ => {
                    let z = tagcase_;
                    false
                }
            }
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

// `n`, if `x` is a module made here, or one named (a load's), its values'
// names noted, for a `with` of it.
pub fn note_layout_x(n: Str, x: &'static Cx) -> () {
    if module_made_p(x) {
        set(cg_layouts(), kayak_rt::heap_cons(clayout(n, get(cg_module_type())), get(cg_layouts())))
    } else if {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(m, a) => {
                not(null_p(layout_in(get(cg_layouts()), m)))
            }
            _ => {
                let y = tagcase_;
                false
            }
        }
    } {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(m, a) => {
                set(cg_layouts(), kayak_rt::heap_cons(clayout(n, car(layout_in(get(cg_layouts()), m))), get(cg_layouts())))
            }
            _ => {
                let y = tagcase_;
                ()
            }
        }
    } else {
        ()
    }
}

// `x` in an `include`'s `(with %include …)` where item `a` is (Fixpt's
// `in-includes`), which binds nothing here, its names bound once already:
// a lambda's body, so that its word is named for the item's place.
pub fn in_includes(x: &'static Cx, a: i64) -> &'static Cx {
    let tagcase_ = x;
    match *tagcase_ {
        Cx::XLambda(ps, body, b) => {
            x_lambda(ps, x_with(x_unit(a), nil::<Str>(), nil::<i64>(), body, a), b)
        }
        _ => {
            let y = tagcase_;
            x_with(x_unit(a), nil::<Str>(), nil::<i64>(), x, a)
        }
    }
}

// Member `i` so, if it is a value of an item.
pub fn member_in_includes(i: &'static Cmem) -> &'static Cmem {
    let tagcase_ = i;
    match *tagcase_ {
        Cmem::Cmem(n, x, k, l, a) => {
            if i64_eq(k, 0i64) {
                i
            } else {
                cmem(n, in_includes(x, a), k, l, a)
            }
        }
    }
}

// The names `xs` (the included values, in order) members `its` use, each
// once, in order: for each member, those it uses in `xs`'s order (Fixpt's
// `c-included-names`).
pub fn included_used(mut its: List<&'static Cmem>, mut xs: Strings, mut acc: Strings) -> Strings {
    loop {
        if null_p(its) {
            return reverse(acc);
        } else {
            let fv = c_free_names(cmem_value(car(its)));
            (its, acc) = (cdr(its), onto(reverse(filter(lambda1s(move |n: Str| {
                (string_member_p(n, fv) && not(string_member_p(n, acc)))
            }), xs)), acc));
            continue;
        }
    }
}

pub fn put_sep_words(ss: Strings) -> Str {
    if null_p(ss) {
        str_lit("")
    } else if null_p(cdr(ss)) {
        car(ss)
    } else {
        string_append(car(ss), string_append(str_lit(" "), put_sep_words(cdr(ss))))
    }
}

pub fn parse_x(e: &'static Sexp) -> &'static Cx {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k, f, p) => {
            big_literal(i64_to_int(k), p)
        }
        Sexp::Big(text, f, p) => {
            big_literal(big_int(text), p)
        }
        Sexp::Chr(c, f, p) => {
            x_char(c, p)
        }
        Sexp::Str(s, f, p) => {
            x_str(s, p)
        }
        Sexp::Real(x, f, p) => {
            x_float(u64_to_int(f64_to_bits(real_value(x))), p)
        }
        Sexp::Sym(n, f, p) => {
            if string_eq_p(n, str_lit("#t")) {
                x_bool(true, p)
            } else if string_eq_p(n, str_lit("#f")) {
                x_bool(false, p)
            } else if string_eq_p(n, str_lit("#u")) {
                x_unit(p)
            } else if (made_here_name_p(n) && not(null_p(made_module(get(cg_made()), n)))) {
                car(made_module(get(cg_made()), n))
            } else {
                x_var(n, p)
            }
        }
        Sexp::Lst(xs, f, l, p) => {
            if null_p(xs) {
                match cg_fail(str_lit("not an expression: ()")) {};
                x_unit(p)
            } else {
                parse_form({
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            n
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("")
                        }
                    }
                }, xs, e, f, p)
            }
        }
    }
}

pub fn parse_xs(es: Sexps) -> Cxs {
    if null_p(es) {
        nil::<&'static Cx>()
    } else {
        kayak_rt::heap_cons(parse_x(car(es)), parse_xs(cdr(es)))
    }
}

/// One or more expressions, an implicit `begin` where the form starts.
pub fn parse_body(forms: Sexps, a: i64) -> &'static Cx {
    if null_p(cdr(forms)) {
        parse_x(car(forms))
    } else {
        x_begin(parse_xs(forms), a)
    }
}

pub fn parse_form(h: Str, xs: Sexps, e: &'static Sexp, f: Str, a: i64) -> &'static Cx {
    if string_eq_p(h, str_lit("lambda")) {
        x_lambda(map(&binder_name, items(second(xs))), parse_body(cdr(cdr(xs)), a), a)
    } else if string_eq_p(h, str_lit("if")) {
        x_if(parse_x(second(xs)), parse_x(car(cdr(cdr(xs)))), parse_x(car(cdr(cdr(cdr(xs))))), a)
    } else if string_eq_p(h, str_lit("let")) {
        x_let(parse_binds(items(second(xs))), parse_body(cdr(cdr(xs)), a), a)
    } else if string_eq_p(h, str_lit("let*")) {
        parse_let_star(items(second(xs)), parse_body(cdr(cdr(xs)), a))
    } else if string_eq_p(h, str_lit("letrec")) {
        x_letrec(parse_typed_binds(items(second(xs))), parse_body(cdr(cdr(xs)), a), a)
    } else if string_eq_p(h, str_lit("begin")) {
        parse_body(cdr(xs), a)
    } else if string_eq_p(h, str_lit("cond")) {
        parse_cond(cdr(xs), a)
    } else if string_eq_p(h, str_lit("and")) {
        parse_and(cdr(xs), a)
    } else if string_eq_p(h, str_lit("or")) {
        parse_or(cdr(xs), a)
    } else if (string_eq_p(h, str_lit("the")) || string_eq_p(h, str_lit("convention"))) {
        parse_x(car(cdr(cdr(xs))))
    } else if string_eq_p(h, str_lit("plambda")) {
        parse_body(cdr(cdr(xs)), a)
    } else if string_eq_p(h, str_lit("proj")) {
        parse_x(second(xs))
    } else if string_eq_p(h, str_lit("quote")) {
        parse_quoted(second(xs), a)
    } else if string_eq_p(h, str_lit("product")) {
        x_product(parse_fields(cdr(xs)), a)
    } else if string_eq_p(h, str_lit("extract")) {
        let (k, o) = (fact_text(get(cg_facts()), f, a, str_lit("extract-index ")), fact_text(get(cg_facts()), f, a, str_lit("blob-offset ")));
        if not(string_eq_p(k, str_lit(""))) {
            x_extract(parse_x(second(xs)), digits_i64(string_chars(k), 0i64), a)
        } else if not(string_eq_p(o, str_lit(""))) {
            x_bloblet(str_lit("%blobref-field"), digits_i64(string_chars(o), 0i64), kayak_rt::heap_cons(parse_x(second(xs)), kayak_rt::nil()), a)
        } else {
            match cg_fail(str_lit("an extract the checker did not see")) {};
            x_unit(a)
        }
    } else if bloblet_form_p(h) {
        parse_bloblet(h, cdr(xs), f, a)
    } else if string_eq_p(h, str_lit("sum")) {
        x_sum(label_of(second(xs)), parse_x(car(cdr(cdr(xs)))), a)
    } else if string_eq_p(h, str_lit("tagcase")) {
        x_tagcase(parse_x(second(xs)), parse_arms(cdr(cdr(xs))), parse_else(cdr(cdr(xs))), a)
    } else if string_eq_p(h, str_lit("module")) {
        parse_module(cdr(xs), a)
    } else if string_eq_p(h, str_lit("extend")) {
        parse_extend(second(xs), third(xs), a)
    } else if string_eq_p(h, str_lit("with")) {
        parse_with(second(xs), parse_body(cdr(cdr(xs)), a), f, a)
    } else if (string_eq_p(h, str_lit("letregion")) || string_eq_p(h, str_lit("letrena")) || string_eq_p(h, str_lit("letreap")) || string_eq_p(h, str_lit("letfreeze"))) {
        x_region(if string_eq_p(h, str_lit("letregion")) {
            0i64
        } else if string_eq_p(h, str_lit("letrena")) {
            1i64
        } else if string_eq_p(h, str_lit("letreap")) {
            2i64
        } else {
            3i64
        }, {
            let tagcase_ = second(xs);
            match *tagcase_ {
                Sexp::Lst(ns, f2, l2, p2) => {
                    sym_name(car(ns))
                }
                _ => {
                    let other = tagcase_;
                    sym_name(second(xs))
                }
            }
        }, parse_body(cdr(cdr(xs)), a), a)
    } else if string_eq_p(h, str_lit("rlambda")) {
        x_rlambda(parse_x(second(xs)), x_lambda(map(&binder_name, items(third(xs))), parse_body(cdr(cdr(cdr(xs))), a), a), a)
    } else if string_eq_p(h, str_lit("prompt")) {
        x_prompt(parse_x(second(xs)), parse_x(third(xs)), parse_x(fourth(xs)), a)
    } else if string_eq_p(h, str_lit("case")) {
        parse_case(cdr(xs), a)
    } else if string_eq_p(h, str_lit("typecase")) {
        parse_typecase(cdr(xs), a)
    } else if (string_eq_p(h, str_lit("quasiquote")) || string_eq_p(h, str_lit("load-module")) || string_eq_p(h, str_lit("vlambda"))) {
        match cg_fail(string_append(str_lit("not yet: "), h)) {};
        x_unit(a)
    } else {
        x_app(parse_x(car(xs)), parse_args(cdr(xs)), a)
    }
}

/// A bloblet's or a blobref's operation (Fixpt's `e-bloblet`), and what
/// the checker found it takes (C152): a field's index, written; a new
/// blobref's size; a scalar's layout, an array's, a flat sum's.
pub fn parse_bloblet(op: Str, args: Sexps, f: Str, a: i64) -> &'static Cx {
    if (string_eq_p(op, str_lit("bloblet-ref")) || string_eq_p(op, str_lit("bloblet-set!"))) {
        x_bloblet(op, {
            let tagcase_ = second(args);
            match *tagcase_ {
                Sexp::Num(k, f2, p2) => {
                    k
                }
                _ => {
                    let other = tagcase_;
                    the::<i64>(-1i64)
                }
            }
        }, kayak_rt::heap_cons(parse_x(car(args)), if string_eq_p(op, str_lit("bloblet-set!")) {
            kayak_rt::heap_cons(parse_x(third(args)), kayak_rt::nil())
        } else {
            nil::<&'static Cx>()
        }), a)
    } else {
        x_bloblet(op, blob_operand(op, f, a), parse_xs(args), a)
    }
}

pub fn parse_case(xs: Sexps, a: i64) -> &'static Cx {
    let clauses = cdr(xs);
    let k = if null_p(cdr(clauses)) {
        the::<i64>(-1i64)
    } else {
        case_kind(car(items(car(items(car(clauses))))))
    };
    let n = case_data_count(clauses);
    let els = items(last(clauses));
    let direct = (i64_eq(size(els), 2i64) && not({
        let tagcase_ = second(els);
        match *tagcase_ {
            Sexp::Lst(ys, f, l, p) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) && i64_eq(n, i64_minus(size(clauses), 1i64)));
    if i64_gt_eq(n, case_tree_from(k, direct)) {
        match cg_fail(str_lit("not yet: a case of many data")) {};
        x_unit(a)
    } else if case_direct_p(xs) {
        parse_case_arms(parse_x(car(xs)), clauses)
    } else {
        x_let(kayak_rt::heap_cons(cbind(str_lit("%case-key"), parse_x(car(xs))), kayak_rt::nil()), parse_case_arms(x_var(str_lit("%case-key"), datum_pos(car(xs))), clauses), a)
    }
}

pub fn parse_case_arms(kv: &'static Cx, clauses: Sexps) -> &'static Cx {
    let c = car(clauses);
    let parts = items(c);
    let ca = datum_pos(c);
    if null_p(cdr(clauses)) {
        parse_body(cdr(parts), ca)
    } else {
        x_if(parse_case_tests(kv, items(car(parts)), ca), parse_body(cdr(parts), ca), parse_case_arms(kv, cdr(clauses)), ca)
    }
}

pub fn parse_case_tests(kv: &'static Cx, data: Sexps, ca: i64) -> &'static Cx {
    let t = parse_case_test(kv, car(data));
    if null_p(cdr(data)) {
        t
    } else {
        x_if(t, x_bool(true, ca), parse_case_tests(kv, cdr(data), ca), ca)
    }
}

pub fn parse_case_test(kv: &'static Cx, d: &'static Sexp) -> &'static Cx {
    let at = datum_pos(d);
    let k = case_kind(d);
    let eq = if i64_eq(k, 0i64) {
        str_lit("=")
    } else if i64_eq(k, 1i64) {
        str_lit("char=?")
    } else if i64_eq(k, 2i64) {
        str_lit("string=?")
    } else if i64_eq(k, 3i64) {
        str_lit("symbol=?")
    } else {
        str_lit("bool=?")
    };
    let lit = if i64_eq(k, 3i64) {
        x_sym(sym_name(d), at)
    } else {
        parse_x(d)
    };
    x_app(x_var(eq, at), kayak_rt::heap_cons(kv, kayak_rt::heap_cons(lit, kayak_rt::nil())), at)
}

pub fn parse_typecase(xs: Sexps, a: i64) -> &'static Cx {
    if case_direct_p(xs) {
        parse_typecase_arms(cdr(xs), sym_name(car(xs)), a)
    } else {
        x_let(kayak_rt::heap_cons(cbind(str_lit("%typecase-value"), parse_x(car(xs))), kayak_rt::nil()), parse_typecase_arms(cdr(xs), str_lit("%typecase-value"), a), a)
    }
}

pub fn parse_typecase_arms(arms: Sexps, tmp: Str, a: i64) -> &'static Cx {
    let parts = items(car(arms));
    if null_p(cdr(arms)) {
        if i64_eq(size(parts), 3i64) {
            x_let(kayak_rt::heap_cons(cbind(sym_name(second(parts)), x_var(tmp, a)), kayak_rt::nil()), parse_x(third(parts)), a)
        } else {
            parse_x(second(parts))
        }
    } else {
        x_if(x_app(x_var(typecase_predicate(sym_name(car(parts))), a), kayak_rt::heap_cons(x_var(tmp, a), kayak_rt::nil()), a), x_let(kayak_rt::heap_cons(cbind(sym_name(second(parts)), x_var(tmp, a)), kayak_rt::nil()), parse_x(third(parts)), a), parse_typecase_arms(cdr(arms), tmp, a), a)
    }
}

pub fn parse_args(es: Sexps) -> Cxs {
    if null_p(es) {
        nil::<&'static Cx>()
    } else {
        kayak_rt::heap_cons(parse_arg(car(es)), parse_args(cdr(es)))
    }
}

/// An argument; a module given where a module type is wanted made one of
/// that type, its values those the type names, in its order (Fixpt's
/// `k-reshapes`), unless it is so already.
pub fn parse_arg(e: &'static Sexp) -> &'static Cx {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            let (want, have) = (fact_text(get(cg_module_facts()), f, p, str_lit("module-arg ")), layout_in(get(cg_layouts()), n));
            if (string_eq_p(want, str_lit("")) || null_p(have)) {
                parse_x(e)
            } else if string_eq_p(want, put_sep_words(car(have))) {
                parse_x(e)
            } else {
                x_reshape(parse_x(e), map(lambda1s(move |w: Str| {
                    kayak_rt::heap_cons(index_in(w, car(have), 0i64), kayak_rt::nil())
                }), split_words(want)), p)
            }
        }
        _ => {
            let other = tagcase_;
            parse_x(e)
        }
    }
}

/// `(with m body …)`: `m`'s values bound in the body, those it names. A
/// module parameter's are its type's, as the checker said; else `m` is
/// a module whose items were read.
pub fn parse_with(m: &'static Sexp, body: &'static Cx, f: Str, a: i64) -> &'static Cx {
    let (spec, known) = (fact_text(get(cg_module_facts()), f, a, str_lit("with-spec ")), {
        let tagcase_ = m;
        match *tagcase_ {
            Sexp::Sym(n, f2, p2) => {
                layout_in(get(cg_layouts()), n)
            }
            _ => {
                let other = tagcase_;
                nil::<List<Str>>()
            }
        }
    });
    if not(string_eq_p(spec, str_lit(""))) {
        with_layout(m, split_words(spec), body, a)
    } else if not(null_p(known)) {
        with_layout(m, car(known), body, a)
    } else {
        match cg_fail(str_lit("not yet: a with of a module not named")) {};
        body
    }
}

pub fn with_layout(m: &'static Sexp, ns: Strings, body: &'static Cx, a: i64) -> &'static Cx {
    x_with(parse_x(m), ns, indices_from(0i64, size(ns)), body, a)
}

/// A module: its own members, in order; then, if it includes modules, a
/// first member `%include`, the module of the modules included, made
/// first, and the names of theirs its members use bound once after it
/// (Fixpt's `with-includes`, `c-note-included!`). The module made is of
/// its own members; then, if its type is not that, one of its type:
/// the values of the modules it includes but hides, then its own that
/// it gives.
pub fn parse_module(forms: Sexps, a: i64) -> &'static Cx {
    let outer = get(cg_layouts());
    let own = parse_items(forms, 2i64);
    let incs = includes_of(forms, false);
    let own_names = map(&cmem_name, filter(lambda1s(move |i: &'static Cmem| {
        i64_gt(cmem_kind(i), 0i64)
    }), own));
    let given = map(&cmem_name, filter(lambda1s(move |i: &'static Cmem| {
        i64_eq(cmem_kind(i), 2i64)
    }), own));
    set(cg_layouts(), outer);
    if (null_p(own) && i64_eq(size(incs), 1i64) && i64_eq(size(forms), 1i64) && {
        let tagcase_ = car(incs);
        match *tagcase_ {
            Cinc::Cinc(m, h, p) => {
                has_prefix_p(m, str_lit("made--load--"))
            }
        }
    }) {
        let tagcase_ = car(incs);
        match *tagcase_ {
            Cinc::Cinc(m, h, p) => {
                set(cg_module_type(), included_layout(m));
                x_var(m, p)
            }
        }
    } else if null_p(incs) {
        set(cg_module_type(), given);
        if string_eq_p(put_sep_words(own_names), put_sep_words(given)) {
            x_module(own, a)
        } else {
            x_reshape(x_module(own, a), map(lambda1s(move |n: Str| {
                kayak_rt::heap_cons(index_in(n, own_names, 0i64), kayak_rt::nil())
            }), given), a)
        }
    } else {
        let at = {
            let tagcase_ = car(incs);
            match *tagcase_ {
                Cinc::Cinc(m, h, p) => {
                    p
                }
            }
        };
        let inc_type = included_values(incs, true);
        let shown = included_values(incs, false);
        let inside = map(&member_in_includes, own);
        let used = included_used(inside, inc_type, nil::<Str>());
        let its = kayak_rt::heap_cons(cmem(str_lit("%include"), include_module(incs, at), 1i64, false, at), onto(map(lambda1s(move |n: Str| {
            cmem(n, x_extract(x_var(str_lit("%include"), at), index_in(n, inc_type, 0i64), at), 0i64, false, at)
        }), used), inside));
        let mine = kayak_rt::heap_cons(str_lit("%include"), own_names);
        set(cg_module_type(), onto(shown, given));
        x_reshape(x_module(its, a), onto(map(lambda1s(move |n: Str| {
            kayak_rt::heap_cons(0i64, kayak_rt::heap_cons(index_in(n, inc_type, 0i64), kayak_rt::nil()))
        }), shown), map(lambda1s(move |n: Str| {
            kayak_rt::heap_cons(index_in(n, mine, 0i64), kayak_rt::nil())
        }), given)), a)
    }
}

/// `(extend e0 e1)` (FX-91's): a module of `e0`, then `e1`, which sees
/// `e0`'s values, in a `with` of it; then, of its type, `e0`'s values,
/// `e1`'s in their place where both give one, then `e1`'s others.
pub fn parse_extend(e0: &'static Sexp, e1: &'static Sexp, a: i64) -> &'static Cx {
    let l0 = included_layout(sym_name(e0));
    let x1 = {
        let tagcase_ = e1;
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                x_var(n, p)
            }
            _ => {
                let other = tagcase_;
                parse_x(e1)
            }
        }
    };
    let l1 = {
        let tagcase_ = e1;
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                included_layout(n)
            }
            _ => {
                let other = tagcase_;
                get(cg_module_type())
            }
        }
    };
    let seen = {
        let tagcase_ = e1;
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                x1
            }
            _ => {
                let other = tagcase_;
                x_with(x_var(str_lit("%extend"), a), l0, indices_from(0i64, size(l0)), x1, a)
            }
        }
    };
    let more = filter(lambda1s(move |n: Str| {
        not(string_member_p(n, l0))
    }), l1);
    set(cg_module_type(), onto(l0, more));
    x_reshape(x_module(kayak_rt::heap_cons(cmem(str_lit("%extend"), parse_x(e0), 1i64, false, a), kayak_rt::heap_cons(cmem(str_lit("%extended"), seen, 1i64, false, a), kayak_rt::nil())), a), onto(map(lambda1s(move |n: Str| {
        if string_member_p(n, l1) {
            kayak_rt::heap_cons(1i64, kayak_rt::heap_cons(index_in(n, l1, 0i64), kayak_rt::nil()))
        } else {
            kayak_rt::heap_cons(0i64, kayak_rt::heap_cons(index_in(n, l0, 0i64), kayak_rt::nil()))
        }
    }), l0), map(lambda1s(move |n: Str| {
        kayak_rt::heap_cons(1i64, kayak_rt::heap_cons(index_in(n, l1, 0i64), kayak_rt::nil()))
    }), more)), a)
}

/// `%include`: the modules included, each a member of it; then, of its
/// type, each of their values in turn.
pub fn include_module(incs: List<&'static Cinc>, at: i64) -> &'static Cx {
    x_reshape(x_module(include_members(incs, 0i64), at), include_paths(incs, 0i64), at)
}

pub fn include_members(incs: List<&'static Cinc>, k: i64) -> List<&'static Cmem> {
    if null_p(incs) {
        nil::<&'static Cmem>()
    } else {
        let tagcase_ = car(incs);
        match *tagcase_ {
            Cinc::Cinc(m, h, p) => {
                kayak_rt::heap_cons(cmem(string_append(if h {
                    str_lit("%hinclude-")
                } else {
                    str_lit("%include-")
                }, i64_to_string(k)), {
                    let made = made_module(get(cg_made()), m);
                    if null_p(made) {
                        x_var(m, p)
                    } else {
                        car(made)
                    }
                }, 2i64, false, p), include_members(cdr(incs), i64_plus(k, 1i64)))
            }
        }
    }
}

pub fn include_paths(incs: List<&'static Cinc>, k: i64) -> Paths {
    if null_p(incs) {
        nil::<List<i64>>()
    } else {
        let tagcase_ = car(incs);
        match *tagcase_ {
            Cinc::Cinc(m, h, p) => {
                onto({
                    let n = size(included_layout(m));
                    map(lambda1s(move |i: i64| {
                        kayak_rt::heap_cons(k, kayak_rt::heap_cons(i, kayak_rt::nil()))
                    }), indices_from(0i64, n))
                }, include_paths(cdr(incs), i64_plus(k, 1i64)))
            }
        }
    }
}

/// The values of the modules included, in order, of those hidden too if
/// `hidden`.
pub fn included_values(incs: List<&'static Cinc>, hidden: bool) -> Strings {
    if null_p(incs) {
        nil::<Str>()
    } else {
        let tagcase_ = car(incs);
        match *tagcase_ {
            Cinc::Cinc(m, h, p) => {
                onto(if (h && not(hidden)) {
                    nil::<Str>()
                } else {
                    included_layout(m)
                }, included_values(cdr(incs), hidden))
            }
        }
    }
}

pub fn included_layout(m: Str) -> Strings {
    let l = layout_in(get(cg_layouts()), m);
    if null_p(l) {
        match cg_fail(string_append(str_lit("not yet: an include of a module not named: "), m)) {};
        nil::<Str>()
    } else {
        car(l)
    }
}

/// A module's `include`s, in order, those in a `hide` hidden.
pub fn includes_of(mut forms: Sexps, mut hidden: bool) -> List<&'static Cinc> {
    loop {
        if null_p(forms) {
            return nil::<&'static Cinc>();
        } else {
            let f = car(forms);
            if head_is_p(f, str_lit("include")) {
                if i64_eq(size(items(f)), 2i64) {
                    return kayak_rt::heap_cons(cinc(sym_name(second(items(f))), hidden, datum_pos(f)), includes_of(cdr(forms), hidden));
                } else {
                    match cg_fail(str_lit("not yet: an include with exceptions")) {};
                    return nil::<&'static Cinc>();
                }
            } else if head_is_p(f, str_lit("hide")) {
                return onto(includes_of(cdr(items(f)), true), includes_of(cdr(forms), hidden));
            } else {
                forms = cdr(forms);
                continue;
            }
        }
    }
}

/// A module's members, in order, each a value; those of a `hide` of kind
/// 1, hidden.
pub fn parse_items(forms: Sexps, kind: i64) -> List<&'static Cmem> {
    if null_p(forms) {
        nil::<&'static Cmem>()
    } else {
        onto(parse_item(car(forms), kind), parse_items(cdr(forms), kind))
    }
}

pub fn parse_item(e: &'static Sexp, kind: i64) -> List<&'static Cmem> {
    let h = {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                if null_p(xs) {
                    str_lit("")
                } else {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            n
                        }
                        _ => {
                            let other2 = tagcase_;
                            str_lit("")
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    };
    if (string_eq_p(h, str_lit("define")) || string_eq_p(h, str_lit("define*"))) {
        let xs = items(e);
        let typed = i64_eq(size(xs), 4i64);
        let n = sym_name(second(xs));
        let x = parse_x(if typed {
            fourth(xs)
        } else {
            third(xs)
        });
        note_layout_x(n, x);
        kayak_rt::heap_cons(cmem(n, x, kind, (typed && not(null_p(lambda_of(x)))), datum_pos(e)), kayak_rt::nil())
    } else if string_eq_p(h, str_lit("define-rec")) {
        parse_rec_members(cdr(items(e)), kind)
    } else if string_eq_p(h, str_lit("define-generative")) {
        map(lambda1s(move |t: &'static Ctop| {
            let tagcase_ = t;
            match *tagcase_ {
                Ctop::TDefine(n, typed, x) => {
                    cmem(n, x, 0i64, false, datum_pos(e))
                }
                _ => {
                    let y = tagcase_;
                    cmem(str_lit(""), x_unit(0i64), 0i64, false, 0i64)
                }
            }
        }), generative_conversions(sym_name(second(items(e))), datum_pos(e)))
    } else if string_eq_p(h, str_lit("define-datatype")) {
        map(lambda1s(move |t: &'static Ctop| {
            let tagcase_ = t;
            match *tagcase_ {
                Ctop::TDefine(n, typed, x) => {
                    cmem(n, x, kind, true, datum_pos(e))
                }
                _ => {
                    let y = tagcase_;
                    cmem(str_lit(""), x_unit(0i64), 0i64, false, 0i64)
                }
            }
        }), dt_constructors(cdr(cdr(items(e))), datum_pos(e)))
    } else if string_eq_p(h, str_lit("import")) {
        map(lambda1s(move |t: &'static Ctop| {
            let tagcase_ = t;
            match *tagcase_ {
                Ctop::TDefine(n, typed, x) => {
                    cmem(n, x, kind, false, datum_pos(e))
                }
                _ => {
                    let y = tagcase_;
                    cmem(str_lit(""), x_unit(0i64), 0i64, false, 0i64)
                }
            }
        }), imports(e))
    } else if string_eq_p(h, str_lit("hide")) {
        parse_items(cdr(items(e)), 1i64)
    } else if (string_eq_p(h, str_lit("define-type")) || string_eq_p(h, str_lit("define-effect")) || string_eq_p(h, str_lit("define-convention")) || string_eq_p(h, str_lit("include")) || string_eq_p(h, str_lit("%loaded"))) {
        nil::<&'static Cmem>()
    } else if {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Str(t, f, p) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } {
        nil::<&'static Cmem>()
    } else {
        match cg_fail(string_append(str_lit("not yet: a module's "), h)) {};
        nil::<&'static Cmem>()
    }
}

/// A `define-rec`'s members, each `(name type expression)`, each where
/// its binding is.
pub fn parse_rec_members(bs: Sexps, kind: i64) -> List<&'static Cmem> {
    if null_p(bs) {
        nil::<&'static Cmem>()
    } else {
        let x = parse_x(third(items(car(bs))));
        kayak_rt::heap_cons(cmem(sym_name(car(items(car(bs)))), x, kind, not(null_p(lambda_of(x))), datum_pos(car(bs))), parse_rec_members(cdr(bs), kind))
    }
}

/// `(import m x …)`: each value `x` defined as `(with m x)`; `(type t
/// …)` and `(effect e …)` name no value.
pub fn imports(e: &'static Sexp) -> List<&'static Ctop> {
    import_names(second(items(e)), cdr(cdr(items(e))), datum_pos(e))
}

pub fn import_names(mut m: &'static Sexp, mut xs: Sexps, mut a: i64) -> List<&'static Ctop> {
    loop {
        if null_p(xs) {
            return nil::<&'static Ctop>();
        } else if {
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(n, f, p) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        } {
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(n, f, p) => {
                    return kayak_rt::heap_cons(t_define(n, false, parse_with(m, x_var(n, p), f, a)), import_names(m, cdr(xs), a));
                }
                _ => {
                    let other = tagcase_;
                    return nil::<&'static Ctop>();
                }
            }
        } else {
            xs = cdr(xs);
            continue;
        }
    }
}

pub fn parse_binds(bs: Sexps) -> Cbinds {
    if null_p(bs) {
        nil::<&'static Cbind>()
    } else {
        kayak_rt::heap_cons(cbind(sym_name(car(items(car(bs)))), parse_x(second(items(car(bs))))), parse_binds(cdr(bs)))
    }
}

/// A `letrec`'s or `define-rec`'s bindings, `(name type expression)`.
pub fn parse_typed_binds(bs: Sexps) -> Cbinds {
    if null_p(bs) {
        nil::<&'static Cbind>()
    } else {
        kayak_rt::heap_cons(cbind(sym_name(car(items(car(bs)))), parse_x(car(cdr(cdr(items(car(bs))))))), parse_typed_binds(cdr(bs)))
    }
}

/// A product's fields, `(label expression)`, in order.
pub fn parse_fields(fs: Sexps) -> Cbinds {
    if null_p(fs) {
        nil::<&'static Cbind>()
    } else {
        kayak_rt::heap_cons(cbind(label_of(car(items(car(fs)))), parse_x(second(items(car(fs))))), parse_fields(cdr(fs)))
    }
}

/// `let*`: nested one-binding `let`s, each where its binding starts.
pub fn parse_let_star(bs: Sexps, body: &'static Cx) -> &'static Cx {
    if null_p(bs) {
        body
    } else {
        x_let(kayak_rt::heap_cons(cbind(sym_name(car(items(car(bs)))), parse_x(second(items(car(bs))))), kayak_rt::nil()), parse_let_star(cdr(bs), body), datum_pos(car(bs)))
    }
}

/// `cond`: nested `if`s, each where its clause starts.
pub fn parse_cond(clauses: Sexps, a: i64) -> &'static Cx {
    let c = car(clauses);
    let parts = items(c);
    if null_p(cdr(clauses)) {
        parse_body(cdr(parts), datum_pos(c))
    } else {
        x_if(parse_x(car(parts)), parse_body(cdr(parts), datum_pos(c)), parse_cond(cdr(clauses), a), datum_pos(c))
    }
}

pub fn parse_and(xs: Sexps, a: i64) -> &'static Cx {
    if null_p(xs) {
        x_bool(true, a)
    } else if null_p(cdr(xs)) {
        parse_x(car(xs))
    } else {
        let x = parse_x(car(xs));
        let rest = parse_and(cdr(xs), a);
        x_if(x, rest, x_bool(false, a), a)
    }
}

pub fn parse_or(xs: Sexps, a: i64) -> &'static Cx {
    if null_p(xs) {
        x_bool(false, a)
    } else if null_p(cdr(xs)) {
        parse_x(car(xs))
    } else {
        let x = parse_x(car(xs));
        let rest = parse_or(cdr(xs), a);
        x_if(x, x_bool(true, a), rest, a)
    }
}

/// A quoted datum, as Fixpt's quote rewrite writes it: a symbol, an atom
/// as itself; a list of `cons` and `nil`, a dotted one's tail its last,
/// a vector `list->vector` of its items' list, interned whole.
pub fn parse_quoted(d: &'static Sexp, a: i64) -> &'static Cx {
    let tagcase_ = d;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            if string_eq_p(n, str_lit("#t")) {
                x_bool(true, a)
            } else if string_eq_p(n, str_lit("#f")) {
                x_bool(false, a)
            } else {
                x_sym(n, a)
            }
        }
        Sexp::Lst(ys, f, l, p) => {
            if null_p(ys) {
                x_var(str_lit("nil"), a)
            } else {
                x_app(x_var(str_lit("%quote"), a), kayak_rt::heap_cons(quoted_item(d, a), kayak_rt::nil()), a)
            }
        }
        _ => {
            let other = tagcase_;
            parse_x(d)
        }
    }
}

pub fn quoted_list(ys: Sexps, a: i64) -> &'static Cx {
    if null_p(ys) {
        x_var(str_lit("nil"), a)
    } else if ({
        let tagcase_ = car(ys);
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                string_eq_p(n, str_lit("."))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && not(null_p(cdr(ys))) && null_p(cdr(cdr(ys)))) {
        quoted_item(second(ys), a)
    } else {
        x_app(x_var(str_lit("cons"), a), kayak_rt::heap_cons(quoted_item(car(ys), a), kayak_rt::heap_cons(quoted_list(cdr(ys), a), kayak_rt::nil())), a)
    }
}

pub fn quoted_item(d: &'static Sexp, a: i64) -> &'static Cx {
    let tagcase_ = d;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            if string_eq_p(n, str_lit("#t")) {
                x_bool(true, a)
            } else if string_eq_p(n, str_lit("#f")) {
                x_bool(false, a)
            } else {
                x_sym(n, a)
            }
        }
        Sexp::Lst(ys, f, l, p) => {
            if (not(null_p(ys)) && {
                let tagcase_ = car(ys);
                match *tagcase_ {
                    Sexp::Sym(n, f2, p2) => {
                        string_eq_p(n, str_lit("#vector"))
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                x_app(x_var(str_lit("list->vector"), a), kayak_rt::heap_cons(quoted_list(cdr(ys), a), kayak_rt::nil()), a)
            } else {
                quoted_list(ys, a)
            }
        }
        _ => {
            let other = tagcase_;
            parse_x(d)
        }
    }
}

/// A `tagcase`'s arms before its `else`: `(tag name body …)` or
/// `(tag (name …) body …)`.
pub fn parse_arms(arms: Sexps) -> List<&'static Carm> {
    if (null_p(arms) || head_is_p(car(arms), str_lit("else"))) {
        nil::<&'static Carm>()
    } else {
        let parts = items(car(arms));
        let b = second(parts);
        kayak_rt::heap_cons({
            let tagcase_ = b;
            match *tagcase_ {
                Sexp::Lst(ns, f, l, p) => {
                    carm(sym_name(car(parts)), true, map(&sym_name, ns), parse_body(cdr(cdr(parts)), datum_pos(car(arms))))
                }
                _ => {
                    let other = tagcase_;
                    carm(sym_name(car(parts)), false, kayak_rt::heap_cons(sym_name(b), kayak_rt::nil()), parse_body(cdr(cdr(parts)), datum_pos(car(arms))))
                }
            }
        }, parse_arms(cdr(arms)))
    }
}

pub fn parse_else(mut arms: Sexps) -> Cbinds {
    loop {
        if null_p(arms) {
            return nil::<&'static Cbind>();
        } else if head_is_p(car(arms), str_lit("else")) {
            let parts = items(car(arms));
            return kayak_rt::heap_cons(cbind(sym_name(second(parts)), parse_body(cdr(cdr(parts)), datum_pos(car(arms)))), kayak_rt::nil());
        } else {
            arms = cdr(arms);
            continue;
        }
    }
}

pub fn parse_top(e: &'static Sexp) -> List<&'static Ctop> {
    let h = {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                if null_p(xs) {
                    str_lit("")
                } else {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            n
                        }
                        _ => {
                            let other2 = tagcase_;
                            str_lit("")
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    };
    if (string_eq_p(h, str_lit("define")) || string_eq_p(h, str_lit("define*"))) {
        let xs = items(e);
        let typed = not(i64_eq(size(xs), 3i64));
        let n = sym_name(second(xs));
        let x = parse_x(if typed {
            fourth(xs)
        } else {
            third(xs)
        });
        note_layout_x(n, x);
        if (made_here_name_p(n) && module_made_p(x)) {
            set(cg_made(), kayak_rt::heap_cons(cmade(n, x), get(cg_made())));
            nil::<&'static Ctop>()
        } else {
            kayak_rt::heap_cons(t_define(n, typed, x), kayak_rt::nil())
        }
    } else if string_eq_p(h, str_lit("define-rec")) {
        kayak_rt::heap_cons(t_define_rec(parse_typed_binds(cdr(items(e)))), kayak_rt::nil())
    } else if (string_eq_p(h, str_lit("define-type")) || string_eq_p(h, str_lit("define-effect")) || string_eq_p(h, str_lit("define-convention"))) {
        nil::<&'static Ctop>()
    } else if string_eq_p(h, str_lit("define-datatype")) {
        dt_constructors(cdr(cdr(items(e))), datum_pos(e))
    } else if string_eq_p(h, str_lit("define-generative")) {
        generative_conversions(sym_name(second(items(e))), datum_pos(e))
    } else if string_eq_p(h, str_lit("import")) {
        imports(e)
    } else if string_eq_p(h, str_lit("include")) {
        match cg_fail(string_append(str_lit("not yet: "), h)) {};
        nil::<&'static Ctop>()
    } else {
        kayak_rt::heap_cons(t_exp(parse_x(e)), kayak_rt::nil())
    }
}

// A literal cell's value: as Fixpt's listing writes it (`literal.rs`).
pub enum Lit {
    LInt(Int),
    LBool(bool),
    LUnit(),
    LNil(),
    LStr(Str),
    LChar(char),
    LF64(Int),
    LSym(Str),
    LPair(&'static Lit, &'static Lit),
    LWord(Str),
}

pub fn l_int(f0: Int) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LInt(f0))
}

pub fn l_bool(f0: bool) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LBool(f0))
}

pub fn l_unit() -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LUnit())
}

pub fn l_nil() -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LNil())
}

pub fn l_str(f0: Str) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LStr(f0))
}

pub fn l_char(f0: char) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LChar(f0))
}

pub fn l_f64(f0: Int) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LF64(f0))
}

pub fn l_sym(f0: Str) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LSym(f0))
}

pub fn l_pair(f0: &'static Lit, f1: &'static Lit) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LPair(f0, f1))
}

pub fn l_word(f0: Str) -> &'static Lit {
    kayak_rt::heap_alloc(Lit::LWord(f0))
}

// An instruction's operand: a number, a literal, a word (by its name), a
// global (by its name), a runtime primitive (by its name).
pub enum Opnd {
    OInt(i64),
    OLit(&'static Lit),
    OWord(Str),
    OGlobal(Str),
    OPrim(Str),
}

pub fn o_int(f0: i64) -> &'static Opnd {
    kayak_rt::heap_alloc(Opnd::OInt(f0))
}

pub fn o_lit(f0: &'static Lit) -> &'static Opnd {
    kayak_rt::heap_alloc(Opnd::OLit(f0))
}

pub fn o_word(f0: Str) -> &'static Opnd {
    kayak_rt::heap_alloc(Opnd::OWord(f0))
}

pub fn o_global(f0: Str) -> &'static Opnd {
    kayak_rt::heap_alloc(Opnd::OGlobal(f0))
}

pub fn o_prim(f0: Str) -> &'static Opnd {
    kayak_rt::heap_alloc(Opnd::OPrim(f0))
}

// One item of a word being built: an instruction (a routine and its
// operands), a label, or a branch to one (Fixpt's `item`).
pub enum Item {
    ItIns(Str, List<&'static Opnd>),
    ItLabel(i64),
    ItBranch(i64),
    ItZbranch(i64),
}

pub fn it_ins(f0: Str, f1: List<&'static Opnd>) -> &'static Item {
    kayak_rt::heap_alloc(Item::ItIns(f0, f1))
}

pub fn it_label(f0: i64) -> &'static Item {
    kayak_rt::heap_alloc(Item::ItLabel(f0))
}

pub fn it_branch(f0: i64) -> &'static Item {
    kayak_rt::heap_alloc(Item::ItBranch(f0))
}

pub fn it_zbranch(f0: i64) -> &'static Item {
    kayak_rt::heap_alloc(Item::ItZbranch(f0))
}

pub type Citems = List<&'static Item>;

pub type Code = Ref<Citems>;

// A word: its name and its items, labels resolved when it is written.
pub enum Word {
    Word(Str, Citems),
}

pub fn word(f0: Str, f1: Citems) -> &'static Word {
    kayak_rt::heap_alloc(Word::Word(f0, f1))
}

// A word's name as the listing says it: up to a tab.
pub fn before_tab(mut cs: Chars, mut acc: Chars) -> Str {
    loop {
        if null_p(cs) {
            return list_to_string(reverse(acc));
        } else if char_eq_p(car(cs), '\t') {
            return list_to_string(reverse(acc));
        } else {
            (cs, acc) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc));
            continue;
        }
    }
}

pub fn shown_name(n: Str) -> Str {
    before_tab(string_chars(n), nil::<char>())
}

// The program's words, the newest first.
pub fn cg_words() -> Ref<List<&'static Word>> {
    kayak_rt::kept_constant!(ONCE: Ref<List<&'static Word>>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<&'static Word>())
    })
}

pub fn cg_labels() -> Ref<i64> {
    kayak_rt::kept_constant!(ONCE: Ref<i64>);
    once(&ONCE, || {
        kayak_rt::heap_new(0i64)
    })
}

pub fn c_fresh() -> i64 {
    let n = get(cg_labels());
    set(cg_labels(), i64_plus(n, 1i64));
    n
}

pub fn c_emit(c: Code, i: &'static Item) -> () {
    set(c, kayak_rt::heap_cons(i, get(c)))
}

pub fn c_op(c: Code, r: Str) -> () {
    c_emit(c, it_ins(r, nil::<&'static Opnd>()))
}

pub fn c_op1(c: Code, r: Str, x: &'static Opnd) -> () {
    c_emit(c, it_ins(r, kayak_rt::heap_cons(x, kayak_rt::nil())))
}

pub fn c_lit(c: Code, x: &'static Lit) -> () {
    c_op1(c, str_lit("lit"), o_lit(x))
}

pub fn c_int(c: Code, n: i64) -> () {
    c_lit(c, l_int(i64_to_int(n)))
}

// Field `k` of a bloblet whose type says it has one.
pub fn c_field(c: Code, k: i64) -> () {
    c_op1(c, str_lit("field"), o_int(k))
}

// Field `k` of the bloblet on top set to the value under it.
pub fn c_field_set(c: Code, k: i64) -> () {
    c_int(c, k);
    c_op(c, str_lit("field!"))
}

// A runtime primitive with `n` arguments.
pub fn c_prim(c: Code, name: Str, n: i64) -> () {
    c_emit(c, it_ins(str_lit("prim"), kayak_rt::heap_cons(o_prim(name), kayak_rt::heap_cons(o_int(n), kayak_rt::nil()))))
}

// That the blobref on top has room for a flat of `size` bytes.
pub fn c_fits(c: Code, size: i64) -> () {
    if i64_gt(size, 1i64) {
        c_int(c, size);
        c_prim(c, str_lit("%fx26-suffix-fits"), 2i64)
    } else {
        ()
    }
}

pub fn second_cx(xs: Cxs) -> &'static Cx {
    car(cdr(xs))
}

// Drop what a mutator left, and leave FX-26's unit value instead.
pub fn c_unit_after(c: Code) -> () {
    c_op(c, str_lit("drop"));
    c_lit(c, l_unit())
}

// What is left when the value is in hand: `return` in tail position.
pub fn c_done(c: Code, tail: bool) -> () {
    if tail {
        c_op(c, str_lit("return"))
    } else {
        ()
    }
}

pub fn c_drops(mut c: Code, mut k: i64) -> () {
    loop {
        if i64_lt_eq(k, 0i64) {
            return ();
        } else {
            c_op(c, str_lit("drop"));
            k = i64_minus(k, 1i64);
            continue;
        }
    }
}

// After a body whose value is on top of `n` values bound from `slot` up:
// the value into `slot`, the others dropped. Nothing in tail position,
// where `return` drops the whole frame.
pub fn c_unbind(c: Code, slot: i64, n: i64, tail: bool) -> () {
    if (tail || i64_eq(n, 0i64)) {
        ()
    } else {
        c_op1(c, str_lit("slot!"), o_int(slot));
        c_drops(c, i64_minus(n, 1i64))
    }
}

pub fn hex_digits(mut n: i64, mut acc: Chars) -> Chars {
    loop {
        let d = i64_remainder(n, 16i64);
        let ch = i64_to_char(if i64_lt(d, 10i64) {
            i64_plus(48i64, d)
        } else {
            i64_plus(87i64, d)
        });
        if i64_lt(n, 16i64) {
            return kayak_rt::heap_cons(ch, acc);
        } else {
            (n, acc) = (i64_quotient(n, 16i64), kayak_rt::heap_cons(ch, acc));
            continue;
        }
    }
}

pub fn hex(n: i64) -> Str {
    list_to_string(hex_digits(n, nil::<char>()))
}

// A float's 64 bits, `k` hex digits of them, as Fixpt's listing writes them.
pub fn hex_bits(mut b: Int, mut k: i64, mut acc: Chars) -> Str {
    loop {
        if i64_eq(k, 0i64) {
            return list_to_string(acc);
        } else {
            let d = int_to_i64(remainder(b, int_lit(16)));
            (b, k, acc) = (quotient(b, int_lit(16)), i64_minus(k, 1i64), kayak_rt::heap_cons(i64_to_char(if i64_lt(d, 10i64) {
                i64_plus(48i64, d)
            } else {
                i64_plus(87i64, d)
            }), acc));
            continue;
        }
    }
}

// A string's characters, each not printable ASCII (and `quote` and `\`) by
// its code, `\xHH;`.
pub fn lit_escaped(s: Str, quote: char) -> Str {
    list_to_string(concat(map(lambda1s(move |ch: char| {
        let k = char_to_i64(ch);
        if (char_eq_p(ch, quote) || i64_eq(k, 92i64) || i64_lt(k, 32i64) || i64_gt(k, 126i64)) {
            string_chars(string_append(str_lit("\\x"), string_append(hex(k), str_lit(";"))))
        } else {
            kayak_rt::heap_cons(ch, kayak_rt::nil())
        }
    }), string_chars(s))))
}

pub fn lit_text(l: &'static Lit) -> Str {
    let tagcase_ = l;
    match *tagcase_ {
        Lit::LInt(n) => {
            int_to_string(n)
        }
        Lit::LBool(v) => {
            if v {
                str_lit("#t")
            } else {
                str_lit("#f")
            }
        }
        Lit::LUnit() => {
            str_lit("|#u|")
        }
        Lit::LNil() => {
            str_lit("()")
        }
        Lit::LStr(s) => {
            string_append(str_lit("\""), string_append(lit_escaped(s, '"'), str_lit("\"")))
        }
        Lit::LChar(ch) => {
            string_append(str_lit("#\\x"), hex(char_to_i64(ch)))
        }
        Lit::LF64(b) => {
            string_append(str_lit("#f64x"), hex_bits(b, 16i64, nil::<char>()))
        }
        Lit::LSym(s) => {
            string_append(str_lit("|"), string_append(lit_escaped(s, '|'), str_lit("|")))
        }
        Lit::LPair(a, d) => {
            string_append(str_lit("("), string_append(lit_text(a), string_append(str_lit(" . "), string_append(lit_text(d), str_lit(")")))))
        }
        Lit::LWord(w) => {
            string_append(str_lit("word "), shown_name(w))
        }
    }
}

pub fn item_size(i: &'static Item) -> i64 {
    let tagcase_ = i;
    match *tagcase_ {
        Item::ItIns(r, os) => {
            i64_plus(1i64, size(os))
        }
        Item::ItLabel(n) => {
            0i64
        }
        Item::ItBranch(n) => {
            2i64
        }
        Item::ItZbranch(n) => {
            2i64
        }
    }
}

// Where each label is: a list of (label, cell) pairs.
pub enum Place {
    Place(i64, i64),
}

pub fn place(f0: i64, f1: i64) -> &'static Place {
    kayak_rt::heap_alloc(Place::Place(f0, f1))
}

pub fn places_of(mut xs: Citems, mut at: i64, mut acc: List<&'static Place>) -> List<&'static Place> {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, at, acc) = (cdr(xs), i64_plus(at, item_size(car(xs))), {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Item::ItLabel(n) => {
                        kayak_rt::heap_cons(place(n, at), acc)
                    }
                    _ => {
                        let y = tagcase_;
                        acc
                    }
                }
            });
            continue;
        }
    }
}

pub fn place_at(mut ps: List<&'static Place>, mut n: i64) -> i64 {
    loop {
        if null_p(ps) {
            return -1i64;
        } else if {
            let tagcase_ = car(ps);
            match *tagcase_ {
                Place::Place(m, at) => {
                    i64_eq(m, n)
                }
            }
        } {
            let tagcase_ = car(ps);
            match *tagcase_ {
                Place::Place(m, at) => {
                    return at;
                }
            }
        } else {
            ps = cdr(ps);
            continue;
        }
    }
}

pub fn range_from(i: i64, n: i64) -> List<i64> {
    if i64_gt_eq(i, n) {
        nil::<i64>()
    } else {
        kayak_rt::heap_cons(i, range_from(i64_plus(i, 1i64), n))
    }
}

pub fn range_to(n: i64) -> List<i64> {
    range_from(0i64, n)
}

pub fn padded(n: i64) -> Str {
    let s = i64_to_string(n);
    string_append(list_to_string(map(lambda1s(move |k: i64| {
        ' '
    }), range_to(i64_minus(4i64, string_length_i64(s))))), s)
}

pub fn second_opnd(os: List<&'static Opnd>) -> &'static Opnd {
    car(cdr(os))
}

pub fn line(at: i64, text: Str) -> Str {
    string_append(str_lit("  "), string_append(padded(at), string_append(str_lit(": "), text)))
}

pub fn put_sep_lines(ss: Strings) -> Str {
    if null_p(ss) {
        str_lit("")
    } else {
        string_append(car(ss), string_append(str_lit("\n"), put_sep_lines(cdr(ss))))
    }
}

pub fn opnd_text(o: &'static Opnd) -> Str {
    let tagcase_ = o;
    match *tagcase_ {
        Opnd::OInt(n) => {
            i64_to_string(n)
        }
        Opnd::OLit(l) => {
            lit_text(l)
        }
        Opnd::OWord(w) => {
            string_append(str_lit("word "), shown_name(w))
        }
        Opnd::OGlobal(g) => {
            g
        }
        Opnd::OPrim(p) => {
            p
        }
    }
}

pub fn words_said(os: List<&'static Opnd>) -> Strings {
    if null_p(os) {
        nil::<Str>()
    } else {
        onto({
            let tagcase_ = car(os);
            match *tagcase_ {
                Opnd::OWord(w) => {
                    kayak_rt::heap_cons(w, kayak_rt::nil())
                }
                Opnd::OLit(l) => {
                    let tagcase_ = l;
                    match *tagcase_ {
                        Lit::LWord(w) => {
                            kayak_rt::heap_cons(w, kayak_rt::nil())
                        }
                        _ => {
                            let y = tagcase_;
                            nil::<Str>()
                        }
                    }
                }
                _ => {
                    let y = tagcase_;
                    nil::<Str>()
                }
            }
        }, words_said(cdr(os)))
    }
}

pub fn ins_text(r: Str, os: List<&'static Opnd>) -> Str {
    if string_eq_p(r, str_lit("closure")) {
        string_append(str_lit("closure "), string_append(opnd_text(car(os)), string_append(str_lit(" over "), opnd_text(second_opnd(os)))))
    } else {
        if null_p(os) {
            r
        } else {
            string_append(r, string_append(str_lit(" "), put_sep_words(map(&opnd_text, os))))
        }
    }
}

// One word's lines, and the words its lines name, in order.
pub enum Wsaid {
    Wsaid(Str, Strings),
}

pub fn wsaid(f0: Str, f1: Strings) -> &'static Wsaid {
    kayak_rt::heap_alloc(Wsaid::Wsaid(f0, f1))
}

pub fn lines_of_items(mut xs: Citems, mut at: i64, mut ps: List<&'static Place>, mut out: Strings, mut named: Strings) -> &'static Wsaid {
    loop {
        if null_p(xs) {
            return wsaid(put_sep_lines(reverse(out)), reverse(named));
        } else {
            let x = car(xs);
            let next = i64_plus(at, item_size(x));
            let tagcase_ = x;
            match *tagcase_ {
                Item::ItLabel(n) => {
                    (xs, at) = (cdr(xs), next);
                    continue;
                }
                Item::ItBranch(n) => {
                    (xs, at, out) = (cdr(xs), next, kayak_rt::heap_cons(line(at, string_append(str_lit("branch → "), i64_to_string(place_at(ps, n)))), out));
                    continue;
                }
                Item::ItZbranch(n) => {
                    (xs, at, out) = (cdr(xs), next, kayak_rt::heap_cons(line(at, string_append(str_lit("0branch → "), i64_to_string(place_at(ps, n)))), out));
                    continue;
                }
                Item::ItIns(r, os) => {
                    (xs, at, out, named) = (cdr(xs), next, kayak_rt::heap_cons(line(at, ins_text(r, os)), out), onto(reverse(words_said(os)), named));
                    continue;
                }
            }
        }
    }
}

// A word's lines, as the listing writes them.
pub fn word_text(xs: Citems) -> Str {
    let tagcase_ = lines_of_items(xs, 0i64, places_of(xs, 0i64, nil::<&'static Place>()), nil::<Str>(), nil::<Str>());
    match *tagcase_ {
        Wsaid::Wsaid(text, named) => {
            text
        }
    }
}

// Whether a word named `name`, as the listing names it, is listed: none,
// one whose lines are `text`, or only others.
pub fn c_named(mut ws: List<&'static Word>, mut name: Str, mut text: Str, mut k: i64) -> i64 {
    loop {
        if null_p(ws) {
            return k;
        } else if {
            let tagcase_ = car(ws);
            match *tagcase_ {
                Word::Word(m, xs) => {
                    string_eq_p(shown_name(m), name)
                }
            }
        } {
            if {
                let tagcase_ = car(ws);
                match *tagcase_ {
                    Word::Word(m, xs) => {
                        string_eq_p(word_text(xs), text)
                    }
                }
            } {
                return 1i64;
            } else {
                (ws, k) = (cdr(ws), 2i64);
                continue;
            }
        } else {
            ws = cdr(ws);
            continue;
        }
    }
}

// A word assembled: made one of the program's, under `name`. Two words
// may have one name in Fixpt's listing (C144): an abstract type's two
// conversions, a datatype's constructors in a module that includes one, a
// global defined again. One the same as a word of its name, cell for cell,
// is listed under it too, as Fixpt lists it (told apart by a tab and a
// number, which the listing leaves out), and kayak-cells takes it as that
// word; one not the same is named apart, `name~N`, so that it runs.
pub fn c_assemble(c: Code, name: Str) -> Str {
    let xs = the::<Citems>(reverse(get(c)));
    let k = c_named(get(cg_words()), name, word_text(xs), 0i64);
    let n = i64_to_string(size(get(cg_words())));
    let own = if i64_eq(k, 0i64) {
        name
    } else if i64_eq(k, 1i64) {
        string_append(name, string_append(str_lit("\t"), n))
    } else {
        string_append(name, string_append(str_lit("~"), n))
    };
    set(cg_words(), kayak_rt::heap_cons(word(own, xs), get(cg_words())));
    own
}

// Where a variable is (Fixpt's `loc`): a slot of the frame, a free value
// of the closure, a global, a `letrec` sibling not made yet, to be in slot
// `i`, or the procedure being compiled, only called in tail position, each
// call a jump to its start.
pub enum Loc {
    AtSlot(i64),
    AtFree(i64),
    AtGlobal(Str),
    AtPending(i64),
    AtLoop(),
}

pub fn at_slot(f0: i64) -> &'static Loc {
    kayak_rt::heap_alloc(Loc::AtSlot(f0))
}

pub fn at_free(f0: i64) -> &'static Loc {
    kayak_rt::heap_alloc(Loc::AtFree(f0))
}

pub fn at_global(f0: Str) -> &'static Loc {
    kayak_rt::heap_alloc(Loc::AtGlobal(f0))
}

pub fn at_pending(f0: i64) -> &'static Loc {
    kayak_rt::heap_alloc(Loc::AtPending(f0))
}

pub fn at_loop() -> &'static Loc {
    kayak_rt::heap_alloc(Loc::AtLoop())
}

pub enum Centry {
    Centry(Str, &'static Loc),
}

pub fn centry(f0: Str, f1: &'static Loc) -> &'static Centry {
    kayak_rt::heap_alloc(Centry::Centry(f0, f1))
}

pub type Cenv = List<&'static Centry>;

pub type Found = List<&'static Loc>;

pub fn c_extend(n: Str, l: &'static Loc, e: Cenv) -> Cenv {
    kayak_rt::heap_cons(centry(n, l), e)
}

pub fn c_find(mut e: Cenv, mut n: Str) -> Found {
    loop {
        if null_p(e) {
            return nil::<&'static Loc>();
        } else if {
            let tagcase_ = car(e);
            match *tagcase_ {
                Centry::Centry(m, l) => {
                    string_eq_p(m, n)
                }
            }
        } {
            let tagcase_ = car(e);
            match *tagcase_ {
                Centry::Centry(m, l) => {
                    return kayak_rt::heap_cons(l, kayak_rt::nil());
                }
            }
        } else {
            e = cdr(e);
            continue;
        }
    }
}

// The globals defined so far, the newest first.
pub fn cg_globals() -> Ref<Strings> {
    kayak_rt::kept_constant!(ONCE: Ref<Strings>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<Str>())
    })
}

// Where `n` is: in the locals, else in the globals; none means standard.
pub fn c_where(e: Cenv, n: Str) -> Found {
    let l = c_find(e, n);
    if not(null_p(l)) {
        l
    } else if string_member_p(n, get(cg_globals())) {
        kayak_rt::heap_cons(at_global(n), kayak_rt::nil())
    } else {
        nil::<&'static Loc>()
    }
}

pub fn c_load(c: Code, l: &'static Loc) -> () {
    let tagcase_ = l;
    match *tagcase_ {
        Loc::AtSlot(i) => {
            c_op1(c, str_lit("slot"), o_int(i))
        }
        Loc::AtFree(i) => {
            c_op1(c, str_lit("free"), o_int(i))
        }
        Loc::AtGlobal(g) => {
            c_op1(c, str_lit("global"), o_global(g))
        }
        Loc::AtPending(i) => {
            match cg_fail(str_lit("a letrec sibling not made yet is only captured")) {}
        }
        Loc::AtLoop() => {
            match cg_fail(str_lit("a loop is only ever called, in tail position")) {}
        }
    }
}

pub fn c_loop_p(l: &'static Loc) -> bool {
    let tagcase_ = l;
    match *tagcase_ {
        Loc::AtLoop() => {
            true
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

pub fn c_global_p(l: &'static Loc) -> bool {
    let tagcase_ = l;
    match *tagcase_ {
        Loc::AtGlobal(g) => {
            true
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

pub fn c_count<A: Copy + 'static>(xs: List<A>) -> i64 {
    size(xs)
}

// Whether every use of `f` in `x` is a call with `n` arguments: where
// `loops` asks, in tail position, which the compiler makes a loop; else in
// any position, and in lambdas inside too, so that `f` is never a value.
pub fn c_calls_only(mut x: &'static Cx, mut f: Str, mut n: i64, mut tail: bool, mut loops: bool) -> bool {
    loop {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(m, a) => {
                return not(string_eq_p(m, f));
            }
            Cx::XLambda(ps, body, a) => {
                return (string_member_p(f, ps) || c_calls_only_inside(body, f, n, loops));
            }
            Cx::XApp(fun, args, a) => {
                return (c_calls_only_all(args, f, n, loops) && {
                    let tagcase_ = fun;
                    match *tagcase_ {
                        Cx::XVar(m, a2) => {
                            if string_eq_p(m, f) {
                                ((tail || not(loops)) && i64_eq(size(args), n))
                            } else {
                                true
                            }
                        }
                        _ => {
                            let y = tagcase_;
                            c_calls_only(fun, f, n, false, loops)
                        }
                    }
                });
            }
            Cx::XIf(t, th, el, a) => {
                return (c_calls_only(t, f, n, false, loops) && c_calls_only(th, f, n, tail, loops) && c_calls_only(el, f, n, tail, loops));
            }
            Cx::XLetrec(bs, body, a) => {
                return (string_member_p(f, c_bound_names(bs, nil::<Str>())) || (c_calls_only_all(c_bound_exps(bs), f, n, loops) && c_calls_only(body, f, n, tail, loops)));
            }
            Cx::XLet(bs, body, a) => {
                return (c_calls_only_all(c_bound_exps(bs), f, n, loops) && (string_member_p(f, c_bound_names(bs, nil::<Str>())) || c_calls_only(body, f, n, tail, loops)));
            }
            Cx::XBegin(es, a) => {
                return c_calls_only_begin(es, f, n, tail, loops);
            }
            Cx::XProduct(fs, a) => {
                return c_calls_only_all(c_bound_exps(fs), f, n, loops);
            }
            Cx::XExtract(p, i, a) => {
                (x, tail) = (p, false);
                continue;
            }
            Cx::XSum(t, v, a) => {
                (x, tail) = (v, false);
                continue;
            }
            Cx::XTagcase(s, arms, els, a) => {
                return (c_calls_only(s, f, n, false, loops) && c_calls_only_arms(arms, f, n, tail, loops) && c_calls_only_else(els, f, n, tail, loops));
            }
            Cx::XBloblet(op, i, xs, a) => {
                return c_calls_only_all(xs, f, n, loops);
            }
            Cx::XPrompt(t, body, h, a) => {
                return (c_calls_only(t, f, n, false, loops) && c_calls_only(h, f, n, false, loops) && c_calls_only_inside(body, f, n, loops));
            }
            Cx::XRegion(k, r, body, a) => {
                return (string_eq_p(r, f) || c_calls_only(body, f, n, false, loops));
            }
            Cx::XRlambda(r, l, a) => {
                return (c_calls_only(r, f, n, false, loops) && c_calls_only(l, f, n, false, loops));
            }
            Cx::XModule(its, a) => {
                return false;
            }
            Cx::XWith(m, ns, ks, body, a) => {
                return false;
            }
            Cx::XReshape(y, ps, a) => {
                (x, tail) = (y, false);
                continue;
            }
            _ => {
                let y = tagcase_;
                return true;
            }
        }
    }
}

pub fn c_calls_only_inside(x: &'static Cx, f: Str, n: i64, loops: bool) -> bool {
    if loops {
        not(c_mentions_p(x, f))
    } else {
        c_calls_only(x, f, n, false, loops)
    }
}

pub fn c_calls_only_all(es: Cxs, f: Str, n: i64, loops: bool) -> bool {
    (null_p(es) || (c_calls_only(car(es), f, n, false, loops) && c_calls_only_all(cdr(es), f, n, loops)))
}

pub fn c_calls_only_begin(es: Cxs, f: Str, n: i64, tail: bool, loops: bool) -> bool {
    if null_p(es) {
        true
    } else if null_p(cdr(es)) {
        c_calls_only(car(es), f, n, tail, loops)
    } else {
        (c_calls_only(car(es), f, n, false, loops) && c_calls_only_begin(cdr(es), f, n, tail, loops))
    }
}

pub fn c_calls_only_arms(arms: List<&'static Carm>, f: Str, n: i64, tail: bool, loops: bool) -> bool {
    (null_p(arms) || ({
        let tagcase_ = car(arms);
        match *tagcase_ {
            Carm::Carm(t, p, ns, body) => {
                (string_member_p(f, ns) || c_calls_only(body, f, n, tail, loops))
            }
        }
    } && c_calls_only_arms(cdr(arms), f, n, tail, loops)))
}

pub fn c_calls_only_else(els: Cbinds, f: Str, n: i64, tail: bool, loops: bool) -> bool {
    (null_p(els) || {
        let tagcase_ = car(els);
        match *tagcase_ {
            Cbind::Cbind(m, x) => {
                (string_eq_p(m, f) || c_calls_only(x, f, n, tail, loops))
            }
        }
    })
}

pub fn c_loops_only(x: &'static Cx, f: Str, n: i64, tail: bool) -> bool {
    c_calls_only(x, f, n, tail, true)
}

// The word being compiled, when it is a `letrec`-bound procedure's: a tail
// call of `c-this-name`, still bound at `c-this-loc`, is a loop.
// `c-this-params` is -1 when the word is no such procedure's.
pub enum This {
    This(Str, &'static Loc, i64),
}

pub fn this(f0: Str, f1: &'static Loc, f2: i64) -> &'static This {
    kayak_rt::heap_alloc(This::This(f0, f1, f2))
}

pub fn c_this_name() -> Ref<Str> {
    kayak_rt::kept_constant!(ONCE: Ref<Str>);
    once(&ONCE, || {
        kayak_rt::heap_new(str_lit("none"))
    })
}

pub fn c_this_loc() -> Ref<&'static Loc> {
    kayak_rt::kept_constant!(ONCE: Ref<&'static Loc>);
    once(&ONCE, || {
        kayak_rt::heap_new(at_loop())
    })
}

pub fn c_this_params() -> Ref<i64> {
    kayak_rt::kept_constant!(ONCE: Ref<i64>);
    once(&ONCE, || {
        kayak_rt::heap_new(-1i64)
    })
}

pub fn c_this_start() -> Ref<i64> {
    kayak_rt::kept_constant!(ONCE: Ref<i64>);
    once(&ONCE, || {
        kayak_rt::heap_new(0i64)
    })
}

pub fn c_this_saved() -> &'static This {
    this(get(c_this_name()), get(c_this_loc()), get(c_this_params()))
}

pub fn c_this_enter_x(me: &'static This, start: i64) -> () {
    let tagcase_ = me;
    match *tagcase_ {
        This::This(n, l, k) => {
            set(c_this_name(), n);
            set(c_this_loc(), l);
            set(c_this_params(), k);
            set(c_this_start(), start)
        }
    }
}

// Whether `l` is where the procedure being compiled is bound: its loop, or
// the free value holding its closure, or a top-level definition's own
// global.
pub fn c_this_loc_p(l: &'static Loc, me: &'static Loc) -> bool {
    let tagcase_ = me;
    match *tagcase_ {
        Loc::AtLoop() => {
            c_loop_p(l)
        }
        Loc::AtFree(i) => {
            let tagcase_ = l;
            match *tagcase_ {
                Loc::AtFree(j) => {
                    i64_eq(i, j)
                }
                _ => {
                    let y = tagcase_;
                    false
                }
            }
        }
        Loc::AtGlobal(g) => {
            c_global_p(l)
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

pub fn c_self_call_p(f: &'static Cx, args: Cxs, e: Cenv, tail: bool) -> bool {
    (tail && i64_gt_eq(get(c_this_params()), 0i64) && {
        let tagcase_ = f;
        match *tagcase_ {
            Cx::XVar(n, a) => {
                (string_eq_p(n, get(c_this_name())) && {
                    let l = c_find(e, n);
                    (not(null_p(l)) && c_this_loc_p(car(l), get(c_this_loc())) && i64_eq(size(args), get(c_this_params())))
                })
            }
            _ => {
                let y = tagcase_;
                false
            }
        }
    })
}

// Into the parameters' slots, from `i` down to 0.
pub fn c_loop_stores(mut c: Code, mut i: i64) -> () {
    loop {
        if i64_lt(i, 0i64) {
            return ();
        } else {
            c_op1(c, str_lit("slot!"), o_int(i));
            i = i64_minus(i, 1i64);
            continue;
        }
    }
}

// The name the next lambda's word gets, if not where its body starts (a
// global's); the name of the lambda whose body is compiled, without where
// it starts, an inner lambda's word named within it, `outer/inner@N`; and
// while a `let`'s binding's init is compiled, the binding's name, which
// the first lambda compiled in it is named for. Each a list of none or one.
pub fn c_word_name() -> Ref<Strings> {
    kayak_rt::kept_constant!(ONCE: Ref<Strings>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<Str>())
    })
}

pub fn c_scope_name() -> Ref<Strings> {
    kayak_rt::kept_constant!(ONCE: Ref<Strings>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<Str>())
    })
}

pub fn c_bind_name() -> Ref<Strings> {
    kayak_rt::kept_constant!(ONCE: Ref<Strings>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<Str>())
    })
}

pub fn c_take(r: Ref<Strings>) -> Strings {
    let v = get(r);
    set(r, nil::<Str>());
    v
}

// A lambda's word's name, but for where its body starts: `named`'s, if it
// has one (a global's); else for the definition it is in, and the name it
// is bound to there (`own`, a `letrec`'s, or `bound`, a `let`'s), or
// `lambda`.
pub fn c_word_base(named: Strings, own: Strings, bound: Strings) -> Str {
    if null_p(named) {
        let (inner, scope) = (if not(null_p(own)) {
            car(own)
        } else if not(null_p(bound)) {
            car(bound)
        } else {
            str_lit("lambda")
        }, get(c_scope_name()));
        if null_p(scope) {
            inner
        } else {
            string_append(car(scope), string_append(str_lit("/"), inner))
        }
    } else {
        car(named)
    }
}

pub fn c_word_symbol(base: Str, named: Strings, body: &'static Cx) -> Str {
    if null_p(named) {
        string_append(base, string_append(str_lit("@"), i64_to_string(cx_start(body))))
    } else {
        car(named)
    }
}

// Whether `name` is an equality of the same word, as `eq` does it.
pub fn std_eq_name_p(n: Str) -> bool {
    (string_eq_p(n, str_lit("char=?")) || string_eq_p(n, str_lit("symbol=?")) || string_eq_p(n, str_lit("wglobal=?")) || string_eq_p(n, str_lit("eq?")) || string_eq_p(n, str_lit("bool=?")))
}

pub fn std_nil_name_p(n: Str) -> bool {
    (string_eq_p(n, str_lit("nil")) || string_eq_p(n, str_lit("no-pair")))
}

pub fn std_primitive(n: Str) -> Str {
    standard::standard_primitive(n)
}

// How many arguments a standard operation takes, as a value, or -1 if it
// is not known here (Fixpt asks its runtime's table for the rest: not yet).
pub fn c_arity(n: Str) -> i64 {
    if string_member_p(n, kayak_rt::heap_cons(str_lit("make-continuation-prompt-tag"), kayak_rt::heap_cons(str_lit("make-escape-tag"), kayak_rt::heap_cons(str_lit("make-continuation-mark-key"), kayak_rt::nil())))) {
        0i64
    } else if string_member_p(n, kayak_rt::heap_cons(str_lit("car"), kayak_rt::heap_cons(str_lit("cdr"), kayak_rt::heap_cons(str_lit("null?"), kayak_rt::heap_cons(str_lit("not"), kayak_rt::heap_cons(str_lit("new"), kayak_rt::heap_cons(str_lit("get"), kayak_rt::heap_cons(str_lit("char->integer"), kayak_rt::heap_cons(str_lit("integer->char"), kayak_rt::heap_cons(str_lit("string-length"), kayak_rt::heap_cons(str_lit("char->string"), kayak_rt::heap_cons(str_lit("symbol->string"), kayak_rt::heap_cons(str_lit("string->symbol"), kayak_rt::heap_cons(str_lit("array-length"), kayak_rt::heap_cons(str_lit("current-marks"), kayak_rt::heap_cons(str_lit("cwcc"), kayak_rt::nil())))))))))))))))) {
        1i64
    } else if string_member_p(n, kayak_rt::heap_cons(str_lit("with-mark"), kayak_rt::heap_cons(str_lit("array-set!"), kayak_rt::heap_cons(str_lit("substring"), kayak_rt::nil())))) {
        3i64
    } else if string_member_p(n, kayak_rt::heap_cons(str_lit("+"), kayak_rt::heap_cons(str_lit("-"), kayak_rt::heap_cons(str_lit("*"), kayak_rt::heap_cons(str_lit("<"), kayak_rt::heap_cons(str_lit(">"), kayak_rt::heap_cons(str_lit("<="), kayak_rt::heap_cons(str_lit(">="), kayak_rt::heap_cons(str_lit("="), kayak_rt::heap_cons(str_lit("modulo"), kayak_rt::heap_cons(str_lit("quotient"), kayak_rt::heap_cons(str_lit("cons"), kayak_rt::heap_cons(str_lit("set-car!"), kayak_rt::heap_cons(str_lit("set-cdr!"), kayak_rt::heap_cons(str_lit("char=?"), kayak_rt::heap_cons(str_lit("string=?"), kayak_rt::heap_cons(str_lit("array-ref"), kayak_rt::heap_cons(str_lit("string-ref"), kayak_rt::heap_cons(str_lit("make-array"), kayak_rt::heap_cons(str_lit("abort-current-continuation"), kayak_rt::heap_cons(str_lit("escape"), kayak_rt::heap_cons(str_lit("set"), kayak_rt::heap_cons(str_lit("marks-of"), kayak_rt::heap_cons(str_lit("call-with-composable-continuation"), kayak_rt::heap_cons(str_lit("call-with-oneshot-continuation"), kayak_rt::heap_cons(str_lit("first-mark"), kayak_rt::nil())))))))))))))))))))))))))) {
        2i64
    } else if std_eq_name_p(n) {
        2i64
    } else {
        -1i64
    }
}

// The boolean on top negated.
pub fn c_not(c: Code) -> () {
    c_lit(c, l_bool(false));
    c_op(c, str_lit("eq"))
}

// The index on top made the field it is in an array, whose elements are
// its fields from 2 on.
pub fn c_array_index(c: Code) -> () {
    c_int(c, 2i64);
    c_op(c, str_lit("int-add"))
}

pub fn c_standard_on(name: Str, n: i64, c: Code) -> () {
    if string_eq_p(name, str_lit("+")) {
        c_op(c, str_lit("int-add"))
    } else if string_eq_p(name, str_lit("-")) {
        c_op(c, str_lit("int-sub"))
    } else if string_eq_p(name, str_lit("<")) {
        c_op(c, str_lit("int-less"))
    } else if string_eq_p(name, str_lit(">")) {
        c_op(c, str_lit("swap"));
        c_op(c, str_lit("int-less"))
    } else if string_eq_p(name, str_lit("<=")) {
        c_op(c, str_lit("swap"));
        c_op(c, str_lit("int-less"));
        c_not(c)
    } else if string_eq_p(name, str_lit(">=")) {
        c_op(c, str_lit("int-less"));
        c_not(c)
    } else if string_eq_p(name, str_lit("=")) {
        c_op(c, str_lit("int-eq"))
    } else if string_eq_p(name, str_lit("cons")) {
        c_op(c, str_lit("cons"))
    } else if string_eq_p(name, str_lit("car")) {
        c_op(c, str_lit("pair-car"))
    } else if string_eq_p(name, str_lit("cdr")) {
        c_op(c, str_lit("pair-cdr"))
    } else if (string_eq_p(name, str_lit("set-car!")) || string_eq_p(name, str_lit("set-cdr!"))) {
        c_prim(c, name, 2i64);
        c_unit_after(c)
    } else if string_eq_p(name, str_lit("new")) {
        c_prim(c, str_lit("%make-box"), 1i64)
    } else if string_eq_p(name, str_lit("get")) {
        c_field(c, 2i64)
    } else if string_eq_p(name, str_lit("set")) {
        c_op(c, str_lit("swap"));
        c_field_set(c, 2i64);
        c_lit(c, l_unit())
    } else if string_eq_p(name, str_lit("null?")) {
        c_lit(c, l_nil());
        c_op(c, str_lit("eq"))
    } else if string_eq_p(name, str_lit("not")) {
        c_not(c)
    } else if string_eq_p(name, str_lit("char->string")) {
        c_prim(c, str_lit("string"), 1i64)
    } else if (string_eq_p(name, str_lit("make-continuation-prompt-tag")) || string_eq_p(name, str_lit("make-escape-tag")) || string_eq_p(name, str_lit("make-continuation-mark-key"))) {
        c_lit(c, l_unit());
        c_prim(c, str_lit("%make-box"), 1i64)
    } else if (string_eq_p(name, str_lit("abort-current-continuation")) || string_eq_p(name, str_lit("escape"))) {
        c_op(c, str_lit("abort"))
    } else if string_eq_p(name, str_lit("call-with-composable-continuation")) {
        c_op(c, str_lit("callcomp"))
    } else if string_eq_p(name, str_lit("call-with-oneshot-continuation")) {
        c_op(c, str_lit("callone"))
    } else if string_eq_p(name, str_lit("cwcc")) {
        c_op(c, str_lit("callcc"))
    } else if string_eq_p(name, str_lit("with-mark")) {
        c_op(c, str_lit("withmark"))
    } else if string_eq_p(name, str_lit("first-mark")) {
        c_op(c, str_lit("firstmark"))
    } else if string_eq_p(name, str_lit("current-marks")) {
        c_op(c, str_lit("currentmarks"))
    } else if string_eq_p(name, str_lit("marks-of")) {
        c_op(c, str_lit("marksof"))
    } else if string_eq_p(name, str_lit("array-ref")) {
        c_array_index(c);
        c_op(c, str_lit("field@"))
    } else if string_eq_p(name, str_lit("array-set!")) {
        c_op(c, str_lit("swap"));
        c_array_index(c);
        c_op(c, str_lit("swap"));
        c_prim(c, str_lit("%bloblet-set!"), 3i64);
        c_unit_after(c)
    } else if string_eq_p(name, str_lit("apply")) {
        c_op(c, str_lit("swap"));
        c_field(c, 3i64);
        c_op1(c, str_lit("call"), o_int(1i64))
    } else if string_eq_p(name, str_lit("array-length")) {
        c_prim(c, str_lit("%bloblet-fields"), 1i64);
        c_int(c, 1i64);
        c_op(c, str_lit("int-sub"))
    } else if string_member_p(name, kayak_rt::heap_cons(str_lit("modulo"), kayak_rt::heap_cons(str_lit("char->integer"), kayak_rt::heap_cons(str_lit("integer->char"), kayak_rt::heap_cons(str_lit("string-append"), kayak_rt::heap_cons(str_lit("string-length"), kayak_rt::heap_cons(str_lit("string-ref"), kayak_rt::heap_cons(str_lit("list->vector"), kayak_rt::heap_cons(str_lit("substring"), kayak_rt::heap_cons(str_lit("string=?"), kayak_rt::heap_cons(str_lit("string->symbol"), kayak_rt::heap_cons(str_lit("symbol->string"), kayak_rt::nil())))))))))))) {
        c_prim(c, name, n)
    } else if std_eq_name_p(name) {
        c_op(c, str_lit("eq"))
    } else {
        let p = std_primitive(name);
        if string_eq_p(p, str_lit("%fx26-identity")) {
            ()
        } else if string_eq_p(p, str_lit("")) {
            match cg_fail(string_append(str_lit("not yet compiled: "), name)) {}
        } else {
            c_prim(c, p, n)
        }
    }
}

// The standard `vsubr`s, `list`, `append` and `string-append`, each with
// the operation of one list that its value applies; "" for the rest.
pub fn c_vsubr_list_op(n: Str) -> Str {
    if string_eq_p(n, str_lit("list")) {
        str_lit("datum-list")
    } else if string_eq_p(n, str_lit("append")) {
        str_lit("%append-list")
    } else if string_eq_p(n, str_lit("string-append")) {
        str_lit("%string-append-list")
    } else {
        str_lit("")
    }
}

pub fn c_vsubr_p(n: Str) -> bool {
    not(string_eq_p(c_vsubr_list_op(n), str_lit("")))
}

// The words made of standard operations as values, by name.
pub fn cg_standard_words() -> Ref<Strings> {
    kayak_rt::kept_constant!(ONCE: Ref<Strings>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<Str>())
    })
}

pub fn c_params_pushed(mut c: Code, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_eq(i, n) {
            return ();
        } else {
            c_op1(c, str_lit("slot"), o_int(i));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

// A standard operation's word as a value: a procedure of its arity that
// applies it to its parameters; a `vsubr`'s, of one list, its operation's
// on that list.
pub fn c_standard_word(name: Str) -> Str {
    if string_member_p(name, get(cg_standard_words())) {
        name
    } else {
        let (n, body) = (c_arity(name), the::<Code>(kayak_rt::heap_new(nil::<&'static Item>())));
        if c_vsubr_p(name) {
            c_op1(body, str_lit("slot"), o_int(0i64));
            c_standard_on(c_vsubr_list_op(name), 1i64, body)
        } else if i64_lt(n, 0i64) {
            match cg_fail(string_append(str_lit("not yet compiled as a value: "), name)) {}
        } else if string_eq_p(name, str_lit("make-array")) {
            c_int(body, 0i64);
            c_params_pushed(body, 0i64, n);
            c_prim(body, str_lit("%make-bloblet-filled"), 3i64)
        } else {
            c_params_pushed(body, 0i64, n);
            c_standard_on(name, n, body)
        };
        c_op(body, str_lit("return"));
        set(cg_standard_words(), kayak_rt::heap_cons(name, get(cg_standard_words())));
        c_assemble(body, name)
    }
}

// A standard operation as a value: a closure of its word over no values; a
// `vsubr`'s given to `%fx26-vlambda`.
pub fn c_standard_value(name: Str, c: Code) -> () {
    let w = c_standard_word(name);
    c_emit(c, it_ins(str_lit("closure"), kayak_rt::heap_cons(o_word(w), kayak_rt::heap_cons(o_int(0i64), kayak_rt::nil()))));
    if c_vsubr_p(name) {
        c_prim(c, str_lit("%fx26-vlambda"), 1i64)
    } else {
        ()
    }
}

// The standard operation `f` names, if it is a name bound nowhere else;
// else "".
pub fn c_standard_name(f: &'static Cx, e: Cenv) -> Str {
    let tagcase_ = f;
    match *tagcase_ {
        Cx::XVar(n, a) => {
            if null_p(c_where(e, n)) {
                n
            } else {
                str_lit("")
            }
        }
        _ => {
            let y = tagcase_;
            str_lit("")
        }
    }
}

// The datum a quote builds, as a literal, where it is made of literals and
// symbols: none, or one.
pub fn c_quoted_cell(x: &'static Cx) -> List<&'static Lit> {
    let tagcase_ = x;
    match *tagcase_ {
        Cx::XInt(n, a) => {
            kayak_rt::heap_cons(l_int(n), kayak_rt::nil())
        }
        Cx::XBool(v, a) => {
            kayak_rt::heap_cons(l_bool(v), kayak_rt::nil())
        }
        Cx::XChar(v, a) => {
            kayak_rt::heap_cons(l_char(v), kayak_rt::nil())
        }
        Cx::XSym(s, a) => {
            kayak_rt::heap_cons(l_sym(s), kayak_rt::nil())
        }
        Cx::XVar(n, a) => {
            if string_eq_p(n, str_lit("nil")) {
                kayak_rt::heap_cons(l_nil(), kayak_rt::nil())
            } else {
                nil::<&'static Lit>()
            }
        }
        Cx::XApp(f, args, a) => {
            if ({
                let tagcase_ = f;
                match *tagcase_ {
                    Cx::XVar(n, b) => {
                        string_eq_p(n, str_lit("cons"))
                    }
                    _ => {
                        let y = tagcase_;
                        false
                    }
                }
            } && i64_eq(size(args), 2i64)) {
                let (h, t) = (c_quoted_cell(car(args)), c_quoted_cell(car(cdr(args))));
                if (null_p(h) || null_p(t)) {
                    nil::<&'static Lit>()
                } else {
                    kayak_rt::heap_cons(l_pair(car(h), car(t)), kayak_rt::nil())
                }
            } else {
                nil::<&'static Lit>()
            }
        }
        _ => {
            let y = tagcase_;
            nil::<&'static Lit>()
        }
    }
}

// What a lambda's word captures, as patches for `letrec` siblings: for each
// sibling it captured before the sibling was made, its free value's index
// and the slot the sibling will be in.
pub enum Patch {
    Patch(i64, i64),
}

pub fn patch(f0: i64, f1: i64) -> &'static Patch {
    kayak_rt::heap_alloc(Patch::Patch(f0, f1))
}

pub type Patches = List<&'static Patch>;

// A lambda's word, and the names its closure captures, in order.
pub enum Cclosing {
    Cclosing(Str, Strings),
}

pub fn cclosing(f0: Str, f1: Strings) -> &'static Cclosing {
    kayak_rt::heap_alloc(Cclosing::Cclosing(f0, f1))
}

pub fn c_param_env(mut ps: Strings, mut i: i64, mut acc: Cenv) -> Cenv {
    loop {
        if null_p(ps) {
            return acc;
        } else {
            (ps, i, acc) = (cdr(ps), i64_plus(i, 1i64), c_extend(car(ps), at_slot(i), acc));
            continue;
        }
    }
}

// The free names that are locals here, not globals or standard names, nor
// a loop, which is not a value.
pub fn c_captured(mut xs: Strings, mut e: Cenv) -> Strings {
    loop {
        if null_p(xs) {
            return nil::<Str>();
        } else if {
            let l = c_find(e, car(xs));
            (null_p(l) || c_loop_p(car(l)) || c_global_p(car(l)))
        } {
            xs = cdr(xs);
            continue;
        } else {
            return kayak_rt::heap_cons(car(xs), c_captured(cdr(xs), e));
        }
    }
}

pub fn c_inner_env(mut xs: Strings, mut acc: Cenv, mut i: i64) -> Cenv {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, acc, i) = (cdr(xs), c_extend(car(xs), at_free(i), acc), i64_plus(i, 1i64));
            continue;
        }
    }
}

// A parameter of the same name hides the procedure.
pub fn c_own_of(ps: Strings, own0: Strings) -> Strings {
    if (null_p(own0) || string_member_p(car(own0), ps)) {
        nil::<Str>()
    } else {
        own0
    }
}

// The scope a lambda's body starts in: its own name, if it does not capture
// it, where `e` has it, a global, or else its loop.
pub fn c_own_scope(own: Strings, fv: Strings, e: Cenv) -> Cenv {
    if (null_p(own) || string_member_p(car(own), fv)) {
        nil::<&'static Centry>()
    } else {
        let l = c_where(e, car(own));
        kayak_rt::heap_cons(centry(car(own), if (not(null_p(l)) && c_global_p(car(l))) {
            car(l)
        } else {
            at_loop()
        }), kayak_rt::nil())
    }
}

pub fn c_this_of(own: Strings, inner: Cenv, n: i64) -> List<&'static This> {
    if null_p(own) {
        nil::<&'static This>()
    } else {
        kayak_rt::heap_cons(this(car(own), car(c_find(inner, car(own))), n), kayak_rt::nil())
    }
}

// Each captured name's value, as the closure will hold it, free value `j`
// on; a sibling not made yet is a placeholder, and one of the patches.
pub fn c_push_all(xs: Strings, e: Cenv, j: i64, c: Code) -> Patches {
    if null_p(xs) {
        nil::<&'static Patch>()
    } else {
        let pending = {
            let tagcase_ = car(c_find(e, car(xs)));
            match *tagcase_ {
                Loc::AtSlot(i) => {
                    c_op1(c, str_lit("slot"), o_int(i));
                    the::<i64>(-1i64)
                }
                Loc::AtFree(i) => {
                    c_op1(c, str_lit("free"), o_int(i));
                    the::<i64>(-1i64)
                }
                Loc::AtPending(s) => {
                    c_lit(c, l_bool(false));
                    s
                }
                _ => {
                    let y = tagcase_;
                    match cg_fail(str_lit("a global or a loop is not captured")) {};
                    the::<i64>(-1i64)
                }
            }
        };
        let rest = c_push_all(cdr(xs), e, i64_plus(j, 1i64), c);
        if i64_lt(pending, 0i64) {
            rest
        } else {
            kayak_rt::heap_cons(patch(j, pending), rest)
        }
    }
}

// A product's members, from the slot after the sum's, each a slot.
pub fn c_members(mut ns: Strings, mut e: Cenv, mut sum_slot: i64, mut slot: i64, mut j: i64, mut c: Code) -> Cenv {
    loop {
        if null_p(ns) {
            return e;
        } else {
            c_op1(c, str_lit("slot"), o_int(i64_plus(sum_slot, 1i64)));
            c_field(c, i64_plus(j, 2i64));
            (ns, e, slot, j) = (cdr(ns), c_extend(car(ns), at_slot(slot), e), i64_plus(slot, 1i64), i64_plus(j, 1i64));
            continue;
        }
    }
}

// Binding `i`'s scope while it is made: each sibling pending, and itself a
// loop if it only calls itself in loops.
pub fn c_letrec_own(mut bs: Cbinds, mut e: Cenv, mut depth: i64, mut k: i64, mut i: i64, mut body: &'static Cx, mut nps: i64) -> Cenv {
    loop {
        if null_p(bs) {
            return e;
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(g, x) => {
                    let loops = (i64_eq(k, i) && c_loops_only(body, g, nps, true));
                    (bs, e, k) = (cdr(bs), c_extend(g, if loops {
                        at_loop()
                    } else {
                        at_pending(i64_plus(depth, k))
                    }, e), i64_plus(k, 1i64));
                    continue;
                }
            }
        }
    }
}

pub fn c_letrec_slots(mut bs: Cbinds, mut e: Cenv, mut d: i64) -> Cenv {
    loop {
        if null_p(bs) {
            return e;
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    (bs, e, d) = (cdr(bs), c_extend(n, at_slot(d), e), i64_plus(d, 1i64));
                    continue;
                }
            }
        }
    }
}

pub fn c_patch_one(mut ps: Patches, mut depth: i64, mut i: i64, mut c: Code) -> () {
    loop {
        if null_p(ps) {
            return ();
        } else {
            let tagcase_ = car(ps);
            match *tagcase_ {
                Patch::Patch(j, s) => {
                    c_op1(c, str_lit("slot"), o_int(s));
                    c_op1(c, str_lit("slot"), o_int(i64_plus(depth, i)));
                    c_field_set(c, i64_plus(3i64, j));
                    ps = cdr(ps);
                    continue;
                }
            }
        }
    }
}

pub fn c_letrec_patch(mut made: List<Patches>, mut depth: i64, mut i: i64, mut c: Code) -> () {
    loop {
        if null_p(made) {
            return ();
        } else {
            c_patch_one(car(made), depth, i, c);
            (made, i) = (cdr(made), i64_plus(i, 1i64));
            continue;
        }
    }
}

// A closure in slot `d` waiting for slot `s`'s value, as its free value
// `j`.
pub enum Wait {
    Wait(i64, i64, i64),
}

pub fn wait(f0: i64, f1: i64, f2: i64) -> &'static Wait {
    kayak_rt::heap_alloc(Wait::Wait(f0, f1, f2))
}

pub fn c_module_slots(its: List<&'static Cmem>, d: i64) -> Cenv {
    if null_p(its) {
        nil::<&'static Centry>()
    } else {
        kayak_rt::heap_cons(centry(cmem_name(car(its)), at_slot(d)), c_module_slots(cdr(its), i64_plus(d, 1i64)))
    }
}

// Whether `x` names any of `later`'s.
pub fn c_names_any_p(x: &'static Cx, later: Cenv) -> bool {
    any_p(lambda1s(move |n: Str| {
        not(null_p(c_find(later, n)))
    }), c_free(x, nil::<Str>(), nil::<Str>()))
}

// Item `n`'s lambda's scope while it is made: each of `later` pending, and
// itself a loop if it only calls itself in loops.
pub fn c_module_own(mut n: Str, mut e: Cenv, mut later: Cenv, mut body: &'static Cx, mut nps: i64) -> Cenv {
    loop {
        if null_p(later) {
            return e;
        } else {
            let tagcase_ = car(later);
            match *tagcase_ {
                Centry::Centry(m, l) => {
                    let loops = (string_eq_p(m, n) && c_loops_only(body, n, nps, true));
                    (e, later) = (c_extend(m, if loops {
                        at_loop()
                    } else {
                        let tagcase_ = l;
                        match *tagcase_ {
                            Loc::AtSlot(s) => {
                                at_pending(s)
                            }
                            _ => {
                                let y = tagcase_;
                                l
                            }
                        }
                    }, e), cdr(later));
                    continue;
                }
            }
        }
    }
}

// Each closure of `ws` waiting for slot `d`, given it.
pub fn c_give_waiting(mut c: Code, mut ws: List<&'static Wait>, mut d: i64) -> () {
    loop {
        if null_p(ws) {
            return ();
        } else {
            let tagcase_ = car(ws);
            match *tagcase_ {
                Wait::Wait(at, j, s) => {
                    if i64_eq(s, d) {
                        c_op1(c, str_lit("slot"), o_int(d));
                        c_op1(c, str_lit("slot"), o_int(at));
                        c_field_set(c, i64_plus(3i64, j))
                    } else {
                        ()
                    };
                    ws = cdr(ws);
                    continue;
                }
            }
        }
    }
}

pub fn c_slots_load(mut c: Code, mut ss: List<i64>) -> () {
    loop {
        if null_p(ss) {
            return ();
        } else {
            c_op1(c, str_lit("slot"), o_int(car(ss)));
            ss = cdr(ss);
            continue;
        }
    }
}

// Each of `ps` of the module in slot `d` pushed: a field, a field of that,
// ...
pub fn c_fields_in(mut c: Code, mut ks: List<i64>) -> () {
    loop {
        if null_p(ks) {
            return ();
        } else {
            c_field(c, i64_plus(car(ks), 2i64));
            ks = cdr(ks);
            continue;
        }
    }
}

pub fn c_reshape_fields(mut c: Code, mut d: i64, mut ps: Paths) -> () {
    loop {
        if null_p(ps) {
            return ();
        } else {
            c_op1(c, str_lit("slot"), o_int(d));
            c_fields_in(c, car(ps));
            ps = cdr(ps);
            continue;
        }
    }
}

pub fn c_exps(es: Cxs, e: Cenv, depth: i64, c: Code) -> i64 {
    if null_p(es) {
        0i64
    } else {
        c_exp(car(es), e, depth, c, false);
        i64_plus(1i64, c_exps(cdr(es), e, i64_plus(depth, 1i64), c))
    }
}

pub fn c_exp(mut x: &'static Cx, mut e: Cenv, mut depth: i64, mut c: Code, mut tail: bool) -> () {
    loop {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(n, a) => {
                let l = c_where(e, n);
                if null_p(l) {
                    if std_nil_name_p(n) {
                        c_lit(c, l_nil())
                    } else {
                        c_standard_value(n, c)
                    }
                } else {
                    c_load(c, car(l))
                };
                return c_done(c, tail);
            }
            Cx::XInt(n, a) => {
                c_lit(c, l_int(n));
                return c_done(c, tail);
            }
            Cx::XBool(v, a) => {
                c_lit(c, l_bool(v));
                return c_done(c, tail);
            }
            Cx::XStr(s, a) => {
                c_lit(c, l_str(s));
                return c_done(c, tail);
            }
            Cx::XChar(ch, a) => {
                c_lit(c, l_char(ch));
                return c_done(c, tail);
            }
            Cx::XFloat(b, a) => {
                c_lit(c, l_f64(b));
                return c_done(c, tail);
            }
            Cx::XSym(s, a) => {
                c_lit(c, l_sym(s));
                return c_done(c, tail);
            }
            Cx::XUnit(a) => {
                c_lit(c, l_unit());
                return c_done(c, tail);
            }
            Cx::XLambda(ps, body, a) => {
                c_lambda(ps, body, e, depth, c, nil::<Str>(), nil::<&'static Cx>());
                return c_done(c, tail);
            }
            Cx::XRlambda(r, l, a) => {
                let tagcase_ = l;
                match *tagcase_ {
                    Cx::XLambda(ps, body, b) => {
                        c_lambda(ps, body, e, depth, c, nil::<Str>(), kayak_rt::heap_cons(r, kayak_rt::nil()));
                        return c_done(c, tail);
                    }
                    _ => {
                        let y = tagcase_;
                        return match cg_fail(str_lit("an rlambda's lambda")) {};
                    }
                }
            }
            Cx::XBloblet(op, i, xs, a) => {
                c_bloblet(op, i, xs, e, depth, c);
                return c_done(c, tail);
            }
            Cx::XPrompt(t, body, h, a) => {
                c_exp(t, e, depth, c, false);
                c_exp(h, e, i64_plus(depth, 1i64), c, false);
                c_lambda(nil::<Str>(), body, e, i64_plus(depth, 2i64), c, nil::<Str>(), nil::<&'static Cx>());
                c_op(c, str_lit("prompt"));
                return c_done(c, tail);
            }
            Cx::XRegion(k, r, body, a) => {
                if (i64_eq(k, 0i64) || i64_eq(k, 3i64)) {
                    x = body;
                    continue;
                } else {
                    c_prim(c, if i64_eq(k, 1i64) {
                        str_lit("%region-enter")
                    } else {
                        str_lit("%reap-enter")
                    }, 0i64);
                    c_exp(body, c_extend(r, at_slot(depth), e), i64_plus(depth, 1i64), c, false);
                    c_prim(c, str_lit("%region-exit"), 2i64);
                    return c_done(c, tail);
                }
            }
            Cx::XApp(f, args, a) => {
                let tagcase_ = f;
                match *tagcase_ {
                    Cx::XLambda(ps, body, b) => {
                        if i64_eq(size(ps), size(args)) {
                            return c_let(map2(lambda2s(move |p: Str, y: &'static Cx| {
                                cbind(p, y)
                            }), ps, args), body, e, depth, c, tail);
                        } else {
                            return c_app(f, args, e, depth, c, tail);
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        return c_app(f, args, e, depth, c, tail);
                    }
                }
            }
            Cx::XIf(t, th, el, a) => {
                let (no, end) = (c_fresh(), c_fresh());
                c_exp(t, e, depth, c, false);
                c_emit(c, it_zbranch(no));
                c_exp(th, e, depth, c, tail);
                if tail {
                    ()
                } else {
                    c_emit(c, it_branch(end))
                };
                c_emit(c, it_label(no));
                c_exp(el, e, depth, c, tail);
                return c_emit(c, it_label(end));
            }
            Cx::XLet(bs, body, a) => {
                return c_let(bs, body, e, depth, c, tail);
            }
            Cx::XLetrec(bs, body, a) => {
                return c_letrec(bs, body, e, depth, c, tail);
            }
            Cx::XBegin(es, a) => {
                return c_begin(es, e, depth, c, tail);
            }
            Cx::XProduct(fs, a) => {
                c_int(c, 37i64);
                c_prim(c, str_lit("%make-frozen"), i64_plus(1i64, c_exps(c_bound_exps(fs), e, i64_plus(depth, 1i64), c)));
                return c_done(c, tail);
            }
            Cx::XExtract(p, i, a) => {
                c_exp(p, e, depth, c, false);
                c_field(c, i64_plus(i, 2i64));
                return c_done(c, tail);
            }
            Cx::XSum(t, v, a) => {
                c_int(c, 36i64);
                c_lit(c, l_sym(t));
                c_exp(v, e, i64_plus(depth, 2i64), c, false);
                c_prim(c, str_lit("%make-frozen"), 3i64);
                return c_done(c, tail);
            }
            Cx::XTagcase(s, arms, els, a) => {
                let end = c_fresh();
                c_exp(s, e, depth, c, false);
                c_arms(arms, els, e, depth, c, tail, end);
                return c_emit(c, it_label(end));
            }
            Cx::XModule(its, a) => {
                return c_module(its, e, depth, c, tail);
            }
            Cx::XWith(m, ns, ks, body, a) => {
                let fv = c_free(body, nil::<Str>(), nil::<Str>());
                let inner = c_with_fields(m, ns, ks, fv, e, e, depth, c);
                let n = size(filter(lambda1s(move |k: Str| {
                    string_member_p(k, fv)
                }), ns));
                c_exp(body, inner, i64_plus(depth, n), c, tail);
                return c_unbind(c, depth, n, tail);
            }
            Cx::XReshape(y, ps, a) => {
                c_exp(y, e, depth, c, false);
                c_int(c, 37i64);
                c_reshape_fields(c, depth, ps);
                c_prim(c, str_lit("%make-frozen"), i64_plus(1i64, size(ps)));
                c_op1(c, str_lit("slot!"), o_int(depth));
                return c_done(c, tail);
            }
        }
    }
}

pub fn c_bloblet(op: Str, i: i64, xs: Cxs, e: Cenv, depth: i64, c: Code) -> () {
    if string_eq_p(op, str_lit("make-bloblet")) {
        c_prim(c, str_lit("%make-bloblet"), c_exps(xs, e, depth, c))
    } else if string_eq_p(op, str_lit("rmake-bloblet")) {
        c_prim(c, str_lit("%region-make-bloblet"), c_exps(xs, e, depth, c))
    } else if string_eq_p(op, str_lit("bloblet-ref")) {
        c_exps(xs, e, depth, c);
        c_field(c, i64_plus(i, 2i64))
    } else if string_eq_p(op, str_lit("bloblet-set!")) {
        c_exp(car(xs), e, depth, c, false);
        c_int(c, i64_plus(i, 2i64));
        c_exp(second_cx(xs), e, i64_plus(depth, 2i64), c, false);
        c_prim(c, str_lit("%bloblet-set!"), 3i64);
        c_unit_after(c)
    } else if string_eq_p(op, str_lit("bloblet-freeze")) {
        c_exps(xs, e, depth, c);
        c_op(c, str_lit("dup"));
        c_lit(c, l_bool(true));
        c_lit(c, l_bool(false));
        c_prim(c, str_lit("%bloblet-freeze!"), 3i64);
        c_op(c, str_lit("drop"))
    } else if string_eq_p(op, str_lit("bloblet-byte")) {
        c_prim(c, str_lit("%bloblet-byte"), c_exps(xs, e, depth, c))
    } else if string_eq_p(op, str_lit("bloblet-set-byte!")) {
        c_prim(c, str_lit("%bloblet-set-byte!"), c_exps(xs, e, depth, c));
        c_unit_after(c)
    } else if string_eq_p(op, str_lit("bloblet-bytes")) {
        c_prim(c, str_lit("%bloblet-bytes"), c_exps(xs, e, depth, c))
    } else if string_eq_p(op, str_lit("blobref-at")) {
        c_prim(c, str_lit("%suffix-ref"), c_exps(xs, e, depth, c));
        c_fits(c, i)
    } else if string_eq_p(op, str_lit("blobref+")) {
        c_prim(c, str_lit("%suffix-ref+"), c_exps(xs, e, depth, c));
        c_fits(c, i)
    } else if string_eq_p(op, str_lit("%blobref-field")) {
        c_exp(car(xs), e, depth, c, false);
        c_int(c, i);
        c_prim(c, str_lit("%suffix-ref+"), 2i64)
    } else if string_eq_p(op, str_lit("blobref-owner")) {
        c_prim(c, str_lit("%suffix-ref-owner"), c_exps(xs, e, depth, c))
    } else if string_eq_p(op, str_lit("blobref-offset")) {
        c_prim(c, str_lit("%suffix-ref-offset"), c_exps(xs, e, depth, c))
    } else if string_eq_p(op, str_lit("blobref-get")) {
        c_exp(car(xs), e, depth, c, false);
        c_int(c, i);
        c_prim(c, str_lit("%fx26-suffix-ref-get"), 2i64)
    } else if string_eq_p(op, str_lit("blobref-index")) {
        c_exps(xs, e, depth, c);
        c_int(c, i);
        c_prim(c, str_lit("%fx26-suffix-ref-index"), 3i64)
    } else {
        c_exp(car(xs), e, depth, c, false);
        c_int(c, i);
        c_exp(second_cx(xs), e, i64_plus(depth, 2i64), c, false);
        c_prim(c, if string_eq_p(op, str_lit("blobref-set!")) {
            str_lit("%fx26-suffix-ref-set!")
        } else {
            str_lit("%fx26-flat-variant!")
        }, 3i64)
    }
}

pub fn c_with_fields(mut m: &'static Cx, mut ns: Strings, mut ks: List<i64>, mut fv: Strings, mut outer: Cenv, mut inner: Cenv, mut depth: i64, mut c: Code) -> Cenv {
    loop {
        if null_p(ns) {
            return inner;
        } else if string_member_p(car(ns), fv) {
            c_exp(m, outer, depth, c, false);
            c_field(c, i64_plus(car(ks), 2i64));
            (ns, ks, inner, depth) = (cdr(ns), cdr(ks), c_extend(car(ns), at_slot(depth), inner), i64_plus(depth, 1i64));
            continue;
        } else {
            (ns, ks) = (cdr(ns), cdr(ks));
            continue;
        }
    }
}

pub fn c_module(its: List<&'static Cmem>, e: Cenv, depth: i64, c: Code, tail: bool) -> () {
    let later = c_module_slots(its, depth);
    let given = c_module_make(its, e, depth, later, nil::<&'static Wait>(), nil::<i64>(), c);
    c_int(c, 37i64);
    c_slots_load(c, reverse(given));
    c_prim(c, str_lit("%make-frozen"), i64_plus(1i64, size(given)));
    c_done(c, tail);
    c_unbind(c, depth, size(its), tail)
}

pub fn c_module_make(mut its: List<&'static Cmem>, mut e: Cenv, mut d: i64, mut later: List<&'static Centry>, mut ws: List<&'static Wait>, mut given: List<i64>, mut c: Code) -> List<i64> {
    loop {
        if null_p(its) {
            return given;
        } else {
            let tagcase_ = car(its);
            match *tagcase_ {
                Cmem::Cmem(n, x, k, lam, at) => {
                    let ps = if (lam && c_names_any_p(x, later)) {
                        let tagcase_ = car(lambda_of(x));
                        match *tagcase_ {
                            Lparts::Lparts(qs, body, region) => {
                                c_lambda(qs, body, c_module_own(n, e, later, body, size(qs)), d, c, kayak_rt::heap_cons(n, kayak_rt::nil()), region)
                            }
                        }
                    } else {
                        c_exp(x, e, d, c, false);
                        the::<Patches>(nil::<&'static Patch>())
                    };
                    let waits = onto(ws, map(lambda1s(move |p: &'static Patch| {
                        let tagcase_ = p;
                        match *tagcase_ {
                            Patch::Patch(j, s) => {
                                wait(d, j, s)
                            }
                        }
                    }), ps));
                    c_give_waiting(c, waits, d);
                    (its, e, d, later, ws, given) = (cdr(its), c_extend(n, at_slot(d), e), i64_plus(d, 1i64), cdr(later), waits, if i64_gt(k, 0i64) {
                        kayak_rt::heap_cons(d, given)
                    } else {
                        given
                    });
                    continue;
                }
            }
        }
    }
}

pub fn c_begin(mut es: Cxs, mut e: Cenv, mut depth: i64, mut c: Code, mut tail: bool) -> () {
    loop {
        if null_p(es) {
            c_lit(c, l_unit());
            return c_done(c, tail);
        } else if null_p(cdr(es)) {
            return c_exp(car(es), e, depth, c, tail);
        } else {
            c_exp(car(es), e, depth, c, false);
            c_op(c, str_lit("drop"));
            es = cdr(es);
            continue;
        }
    }
}

pub fn c_let_bind(mut bs: Cbinds, mut outer: Cenv, mut inner: Cenv, mut depth: i64, mut c: Code) -> Cenv {
    loop {
        if null_p(bs) {
            return inner;
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    set(c_bind_name(), kayak_rt::heap_cons(n, kayak_rt::nil()));
                    c_exp(x, outer, depth, c, false);
                    set(c_bind_name(), nil::<Str>());
                    (bs, inner, depth) = (cdr(bs), c_extend(n, at_slot(depth), inner), i64_plus(depth, 1i64));
                    continue;
                }
            }
        }
    }
}

pub fn c_let(bs: Cbinds, body: &'static Cx, e: Cenv, depth: i64, c: Code, tail: bool) -> () {
    let inner = c_let_bind(bs, e, e, depth, c);
    let n = size(bs);
    c_exp(body, inner, i64_plus(depth, n), c, tail);
    c_unbind(c, depth, n, tail)
}

pub fn c_letrec(bs: Cbinds, body: &'static Cx, e: Cenv, depth: i64, c: Code, tail: bool) -> () {
    let made = c_letrec_make(bs, bs, e, depth, 0i64, c);
    let n = size(bs);
    c_letrec_patch(made, depth, 0i64, c);
    c_exp(body, c_letrec_slots(bs, e, depth), i64_plus(depth, n), c, tail);
    c_unbind(c, depth, n, tail)
}

pub fn c_letrec_make(all: Cbinds, bs: Cbinds, e: Cenv, depth: i64, i: i64, c: Code) -> List<Patches> {
    if null_p(bs) {
        nil::<List<&'static Patch>>()
    } else {
        let tagcase_ = car(bs);
        match *tagcase_ {
            Cbind::Cbind(name, x) => {
                if null_p(lambda_of(x)) {
                    match cg_fail(str_lit("a letrec binds only lambdas")) {};
                    nil::<List<&'static Patch>>()
                } else {
                    let tagcase_ = car(lambda_of(x));
                    match *tagcase_ {
                        Lparts::Lparts(ps, body, region) => {
                            let made = c_lambda(ps, body, c_letrec_own(all, e, depth, 0i64, i, body, size(ps)), i64_plus(depth, i), c, kayak_rt::heap_cons(name, kayak_rt::nil()), region);
                            let rest = c_letrec_make(all, cdr(bs), e, depth, i64_plus(i, 1i64), c);
                            kayak_rt::heap_cons(made, rest)
                        }
                    }
                }
            }
        }
    }
}

pub fn c_lambda(ps: Strings, body: &'static Cx, e: Cenv, depth: i64, c: Code, own0: Strings, region: Cxs) -> Patches {
    if null_p(region) {
        ()
    } else {
        c_exp(car(region), e, depth, c, false)
    };
    let tagcase_ = c_lambda_word(ps, body, e, own0);
    match *tagcase_ {
        Cclosing::Cclosing(w, fv) => {
            let ps2 = c_push_all(fv, e, 0i64, c);
            if null_p(region) {
                c_emit(c, it_ins(str_lit("closure"), kayak_rt::heap_cons(o_word(w), kayak_rt::heap_cons(o_int(size(fv)), kayak_rt::nil()))))
            } else {
                c_lit(c, l_word(w));
                c_prim(c, str_lit("%region-closure"), i64_plus(2i64, size(fv)))
            };
            ps2
        }
    }
}

pub fn c_lambda_word(ps: Strings, body: &'static Cx, e: Cenv, own0: Strings) -> &'static Cclosing {
    let named = c_take(c_word_name());
    let bound = c_take(c_bind_name());
    let fv = c_captured(c_free(body, ps, nil::<Str>()), e);
    let own = c_own_of(ps, own0);
    let inner = c_inner_env(fv, c_param_env(ps, 0i64, c_own_scope(own, fv, e)), 0i64);
    let n = size(ps);
    let body_code = the::<Code>(kayak_rt::heap_new(nil::<&'static Item>()));
    let outer = c_this_saved();
    let outer_start = get(c_this_start());
    let me = c_this_of(own, inner, n);
    let base = c_word_base(named, own0, bound);
    let outer_scope = get(c_scope_name());
    set(c_scope_name(), kayak_rt::heap_cons(base, kayak_rt::nil()));
    if null_p(me) {
        set(c_this_params(), -1i64)
    } else {
        let start = c_fresh();
        c_this_enter_x(car(me), start);
        c_emit(body_code, it_label(start))
    };
    c_exp(body, inner, n, body_code, true);
    c_this_enter_x(outer, outer_start);
    let w = c_assemble(body_code, c_word_symbol(base, named, body));
    set(c_scope_name(), outer_scope);
    cclosing(w, fv)
}

pub fn c_app(f: &'static Cx, args: Cxs, e: Cenv, depth: i64, c: Code, tail: bool) -> () {
    if c_self_call_p(f, args, e, tail) {
        c_exps(args, e, depth, c);
        c_loop_stores(c, i64_minus(get(c_this_params()), 1i64));
        c_drops(c, i64_minus(depth, get(c_this_params())));
        c_emit(c, it_branch(get(c_this_start())))
    } else {
        let standard = c_standard_name(f, e);
        if string_eq_p(standard, str_lit("")) {
            let n = c_exps(args, e, depth, c);
            c_exp(f, e, i64_plus(depth, n), c, false);
            c_op1(c, if tail {
                str_lit("ttailcall")
            } else {
                str_lit("tcall")
            }, o_int(n))
        } else if (string_eq_p(standard, str_lit("%quote")) && i64_eq(size(args), 1i64) && not(null_p(c_quoted_cell(car(args))))) {
            c_lit(c, car(c_quoted_cell(car(args))));
            c_done(c, tail)
        } else if string_eq_p(standard, str_lit("%quote")) {
            c_exp(car(args), e, depth, c, false);
            c_prim(c, str_lit("%fx26-intern-datum"), 1i64);
            c_done(c, tail)
        } else if (tail && string_eq_p(standard, str_lit("with-mark"))) {
            c_exps(args, e, depth, c);
            c_op(c, str_lit("withmark-tail"))
        } else if string_eq_p(standard, str_lit("make-array")) {
            c_int(c, 0i64);
            c_exps(args, e, i64_plus(depth, 1i64), c);
            c_prim(c, str_lit("%make-bloblet-filled"), 3i64);
            c_done(c, tail)
        } else {
            c_standard_on(standard, c_exps(args, e, depth, c), c);
            c_done(c, tail)
        }
    }
}

pub fn c_arms(mut arms: List<&'static Carm>, mut els: Cbinds, mut e: Cenv, mut depth: i64, mut c: Code, mut tail: bool, mut end: i64) -> () {
    loop {
        if null_p(arms) {
            if null_p(els) {
                c_lit(c, l_bool(false));
                c_int(c, 0i64);
                c_op(c, str_lit("field@"));
                return c_done(c, tail);
            } else {
                let tagcase_ = car(els);
                match *tagcase_ {
                    Cbind::Cbind(n, x) => {
                        c_exp(x, c_extend(n, at_slot(depth), e), i64_plus(depth, 1i64), c, tail);
                        return c_unbind(c, depth, 1i64, tail);
                    }
                }
            }
        } else {
            let tagcase_ = car(arms);
            match *tagcase_ {
                Carm::Carm(tag, whole, ns, body) => {
                    let next = c_fresh();
                    c_op1(c, str_lit("slot"), o_int(depth));
                    c_field(c, 2i64);
                    c_lit(c, l_sym(tag));
                    c_op(c, str_lit("eq"));
                    c_emit(c, it_zbranch(next));
                    c_op1(c, str_lit("slot"), o_int(depth));
                    c_field(c, 3i64);
                    {
                        let (bound, k) = (if whole {
                            c_members(ns, e, depth, i64_plus(depth, 2i64), 0i64, c)
                        } else {
                            c_extend(car(ns), at_slot(i64_plus(depth, 1i64)), e)
                        }, if whole {
                            i64_plus(1i64, size(ns))
                        } else {
                            the::<i64>(1i64)
                        });
                        c_exp(body, bound, i64_plus(depth, i64_plus(1i64, k)), c, tail);
                        c_unbind(c, depth, i64_plus(k, 1i64), tail);
                        if tail {
                            ()
                        } else {
                            c_emit(c, it_branch(end))
                        }
                    };
                    c_emit(c, it_label(next));
                    arms = cdr(arms);
                    continue;
                }
            }
        }
    }
}

pub fn c_push_global_x(n: Str) -> () {
    set(cg_globals(), kayak_rt::heap_cons(n, get(cg_globals())))
}

// The next lambda's word named for global `n`, when `x`, its definition, is
// a lambda.
pub fn c_name_for_x(n: Str, x: &'static Cx) -> () {
    let tagcase_ = x;
    match *tagcase_ {
        Cx::XLambda(ps, body, a) => {
            set(c_word_name(), kayak_rt::heap_cons(n, kayak_rt::nil()))
        }
        _ => {
            let y = tagcase_;
            ()
        }
    }
}

pub fn c_rec_globals_x(mut bs: Cbinds) -> () {
    loop {
        if null_p(bs) {
            return ();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    c_push_global_x(n);
                    bs = cdr(bs);
                    continue;
                }
            }
        }
    }
}

// Each of a `define-rec`'s values made, and its global set.
pub fn c_rec_fill_x(mut bs: Cbinds, mut c: Code) -> () {
    loop {
        if null_p(bs) {
            return ();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    c_name_for_x(n, x);
                    c_exp(x, nil::<&'static Centry>(), 0i64, c, false);
                    c_op1(c, str_lit("global!"), o_global(n));
                    bs = cdr(bs);
                    continue;
                }
            }
        }
    }
}

pub fn parse_tops(fs: Sexps) -> List<&'static Ctop> {
    if null_p(fs) {
        nil::<&'static Ctop>()
    } else {
        let t = parse_top(car(fs));
        onto(t, parse_tops(cdr(fs)))
    }
}

// Each form in turn; the last expression's value is left on the stack.
pub fn c_tops(mut ts: List<&'static Ctop>, mut c: Code, mut has_value: bool) -> bool {
    loop {
        if null_p(ts) {
            return has_value;
        } else {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Ctop::TDefine(n, typed, x) => {
                    if has_value {
                        c_op(c, str_lit("drop"))
                    } else {
                        ()
                    };
                    {
                        let tagcase_ = x;
                        match *tagcase_ {
                            Cx::XLambda(ps, body, a) => {
                                if typed {
                                    c_push_global_x(n);
                                    set(c_word_name(), kayak_rt::heap_cons(n, kayak_rt::nil()));
                                    c_lambda(ps, body, nil::<&'static Centry>(), 0i64, c, nil::<Str>(), nil::<&'static Cx>());
                                    c_op1(c, str_lit("global!"), o_global(n))
                                } else {
                                    c_exp(x, nil::<&'static Centry>(), 0i64, c, false);
                                    c_push_global_x(n);
                                    c_op1(c, str_lit("global!"), o_global(n))
                                }
                            }
                            _ => {
                                let y = tagcase_;
                                c_exp(x, nil::<&'static Centry>(), 0i64, c, false);
                                c_push_global_x(n);
                                c_op1(c, str_lit("global!"), o_global(n))
                            }
                        }
                    };
                    (ts, has_value) = (cdr(ts), false);
                    continue;
                }
                Ctop::TDefineRec(bs) => {
                    if has_value {
                        c_op(c, str_lit("drop"))
                    } else {
                        ()
                    };
                    c_rec_globals_x(bs);
                    c_rec_fill_x(bs, c);
                    (ts, has_value) = (cdr(ts), false);
                    continue;
                }
                Ctop::TExp(x) => {
                    if has_value {
                        c_op(c, str_lit("drop"))
                    } else {
                        ()
                    };
                    c_exp(x, nil::<&'static Centry>(), 0i64, c, false);
                    (ts, has_value) = (cdr(ts), true);
                    continue;
                }
                Ctop::TNone() => {
                    ts = cdr(ts);
                    continue;
                }
            }
        }
    }
}

// A program's one word, which runs it and leaves the value of its last
// expression (unit, if it has none), and the words it makes.
pub fn compile_cells(forms: Sexps, fs: Facts) -> () {
    let c = the::<Code>(kayak_rt::heap_new(nil::<&'static Item>()));
    set(cg_facts(), fs);
    set(cg_module_facts(), filter(lambda1s(move |x: &'static Fact| {
        let tagcase_ = x;
        match *tagcase_ {
            Fact::Fact(f, p, what) => {
                (has_prefix_p(what, str_lit("with-spec ")) || has_prefix_p(what, str_lit("module-arg ")))
            }
        }
    }), fs));
    set(cg_layouts(), nil::<&'static Clayout>());
    set(cg_made(), nil::<&'static Cmade>());
    set(cg_words(), nil::<&'static Word>());
    set(cg_globals(), nil::<Str>());
    set(cg_standard_words(), nil::<Str>());
    set(c_this_params(), -1i64);
    if c_tops(parse_tops(forms), c, false) {
        ()
    } else {
        c_lit(c, l_unit())
    };
    c_op(c, str_lit("exit"));
    c_assemble(c, str_lit("program"));
    ()
}

pub fn cells_of(mut xs: Citems, mut n: i64) -> i64 {
    loop {
        if null_p(xs) {
            return n;
        } else {
            (xs, n) = (cdr(xs), i64_plus(n, item_size(car(xs))));
            continue;
        }
    }
}

pub fn word_named(mut ws: List<&'static Word>, mut n: Str) -> List<&'static Word> {
    loop {
        if null_p(ws) {
            return nil::<&'static Word>();
        } else if {
            let tagcase_ = car(ws);
            match *tagcase_ {
                Word::Word(m, xs) => {
                    string_eq_p(m, n)
                }
            }
        } {
            return kayak_rt::heap_cons(car(ws), kayak_rt::nil());
        } else {
            ws = cdr(ws);
            continue;
        }
    }
}

// The listing: from `program`, each word reached, as `disasm.rs` walks
// them: the words a word names pushed in order, the last pushed next.
pub fn listing_from(mut todo: Strings, mut seen: Strings, mut out: Str) -> Str {
    loop {
        if null_p(todo) {
            return out;
        } else if string_member_p(car(todo), seen) {
            todo = cdr(todo);
            continue;
        } else {
            let w = word_named(get(cg_words()), car(todo));
            if null_p(w) {
                (todo, seen) = (cdr(todo), kayak_rt::heap_cons(car(todo), seen));
                continue;
            } else {
                let tagcase_ = car(w);
                match *tagcase_ {
                    Word::Word(name, xs) => {
                        let tagcase_ = lines_of_items(xs, 0i64, places_of(xs, 0i64, nil::<&'static Place>()), nil::<Str>(), nil::<Str>());
                        match *tagcase_ {
                            Wsaid::Wsaid(text, named) => {
                                (todo, seen, out) = (onto(reverse(named), cdr(todo)), kayak_rt::heap_cons(name, seen), string_append(out, string_append(str_lit("\nword "), string_append(shown_name(name), string_append(str_lit(" ("), string_append(i64_to_string(cells_of(xs, 0i64)), string_append(str_lit(" cells, cellular):\n"), text)))))));
                                continue;
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn cells_listing() -> Str {
    listing_from(kayak_rt::heap_cons(str_lit("program"), kayak_rt::nil()), nil::<Str>(), str_lit(""))
}

